// ---- core.js ----
(function (window, $) {
  // 创建kiko命名空间
  const kiko = {
    version: '1.0.0',
    ui: {},
    utils: {},
  };

  // 核心功能
  kiko.core = {
    // 日志功能
    log: function (message, data, level = 'info') {
      if (!kiko.config.debug) return;

      const prefix = `[Kiko]`;
      switch (level) {
        case 'error':
          console.error(`${prefix} ${message}`, data || '');
          break;
        case 'warn':
          console.warn(`${prefix} ${message}`, data || '');
          break;
        default:
          console.log(`${prefix} ${message}`, data || '');
      }
    },

    // 错误处理
    handleError: function (type, errorData, callback) {
      kiko.core.log(errorData.message, errorData, 'error');

      if (
        kiko.config.errorHandler &&
        typeof kiko.config.errorHandler === 'function'
      ) {
        try {
          kiko.config.errorHandler(type, errorData);
        } catch (error) {
          console.error('[Kiko Error] 执行错误处理器时出错:', error);
        }
      }

      if (typeof callback === 'function') {
        callback(errorData);
      }
    },

    // AJAX请求封装
    ajax: function (options) {
      // 默认设置
      const defaults = {
        method: 'GET',
        cache: kiko.config.cache,
        headers: {},
      };

      // 合并选项
      const settings = $.extend({}, defaults, options);

      // 添加缓存控制
      if (!settings.cache) {
        settings.headers['Cache-Control'] =
          'no-cache, no-store, must-revalidate';
        settings.headers['Pragma'] = 'no-cache';
        settings.headers['Expires'] = '0';
      }

      kiko.core.log('发送AJAX请求', settings);

      // 返回jQuery ajax Promise
      return $.ajax(settings)
        .done(function (data, textStatus, jqXHR) {
          kiko.core.log('AJAX请求成功', {
            url: settings.url,
            status: textStatus,
          });
        })
        .fail(function (jqXHR, textStatus, errorThrown) {
          kiko.core.handleError('ajax_error', {
            message: 'AJAX请求失败',
            error: errorThrown,
            status: textStatus,
            xhr: jqXHR,
            url: settings.url,
          });
        });
    },

    // 动画效果
    animate: function ($element, animation, options = {}) {
      const duration = options.duration || kiko.config.animation.duration;
      const complete = options.complete || function () {};

      switch (animation) {
        case 'fade':
          if (options.hide) {
            return $element
              .fadeOut({ duration: duration })
              .promise()
              .then(complete);
          } else {
            return $element
              .fadeIn({ duration: duration })
              .promise()
              .then(complete);
          }
        case 'slide':
          if (options.hide) {
            return $element
              .slideUp({ duration: duration })
              .promise()
              .then(complete);
          } else {
            return $element
              .slideDown({ duration: duration })
              .promise()
              .then(complete);
          }
        default:
          if (options.hide) {
            $element.hide();
          } else {
            $element.show();
          }
          return $.Deferred().resolve().promise().then(complete);
      }
    },

    // DOM操作工具
    dom: {
      // 生成唯一ID
      generateId: function (prefix = 'kiko-') {
        return prefix + Math.random().toString(36).substring(2, 10);
      },

      // 收集元素上的data-*属性
      collectDataAttributes: function ($element, exclude = []) {
        const data = {};
        const attrs = $element.get(0).attributes;

        for (let i = 0; i < attrs.length; i++) {
          const attr = attrs[i];
          if (attr.name.startsWith('data-')) {
            // 转换data-attribute-name为attributeName
            const key = attr.name
              .slice(5)
              .replace(/-([a-z])/g, function (match, letter) {
                return letter.toUpperCase();
              });

            if (!exclude.includes(key)) {
              data[key] = attr.value;
            }
          }
        }

        return data;
      },

      // 简单模板替换
      template: function (str, data) {
        return str.replace(/\{([^{}]*)\}/g, function (match, key) {
          const value = data[key];
          return typeof value !== 'undefined' ? value : match;
        });
      },
    },

    // 事件总线
    eventBus: {
      events: {},

      on: function (event, callback) {
        if (!this.events[event]) {
          this.events[event] = [];
        }
        this.events[event].push(callback);
        return this; // 支持链式调用
      },

      off: function (event, callback) {
        if (!this.events[event]) return this;

        if (callback) {
          this.events[event] = this.events[event].filter(
            (cb) => cb !== callback,
          );
        } else {
          delete this.events[event];
        }
        return this; // 支持链式调用
      },

      trigger: function (event, data) {
        if (!this.events[event]) return this;

        this.events[event].forEach((callback) => {
          try {
            callback(data);
          } catch (e) {
            kiko.core.log(`事件处理错误: ${e.message}`, e, 'error');
          }
        });
        return this; // 支持链式调用
      },
    },

    // 缓存系统
    cache: {
      data: {},

      set: function (key, value, ttl = null) {
        const item = {
          value: value,
          expires: ttl ? Date.now() + ttl * 1000 : null,
        };
        this.data[key] = item;
        return value;
      },

      get: function (key) {
        const item = this.data[key];

        if (!item) return null;

        // 检查是否过期
        if (item.expires && item.expires < Date.now()) {
          this.remove(key);
          return null;
        }

        return item.value;
      },

      remove: function (key) {
        delete this.data[key];
      },

      clear: function () {
        this.data = {};
      },
    },

    // 通用工具函数
    utils: {
      /**
       * 检测Tailwind CSS是否可用
       * @returns {boolean} 是否可用
       */
      isTailwindAvailable: function () {
        // 一个简单的检测方法是创建一个元素，应用Tailwind类，然后检查计算样式
        const testElement = document.createElement('div');
        testElement.className = 'hidden';
        document.body.appendChild(testElement);

        const computedStyle = window.getComputedStyle(testElement);
        const isHidden = computedStyle.display === 'none';

        document.body.removeChild(testElement);
        return isHidden; // 如果正确应用了hidden类，则返回true
      },
    },
  };

  // 全局配置
  kiko.config = {
    debug: false,
    errorHandler: null,
    baseUrl: '',
    cache: true,
    animation: {
      duration: 300,
      type: 'fade',
    },
  };

  // 扩展jQuery原型，提取自util.js
  if ($) {
    $.fn.extend({
      disableFormInputs: function (disabled) {
        return this.find(':input').prop('disabled', disabled);
      },
    });

    // String扩展方法，提取自util.js
    if (!String.prototype.trim) {
      String.prototype.trim = function (arg) {
        // 特殊字符转义函数
        const escapeSpecialChars = (arg) => {
          const specialChars = '$(*+.[?^{|';
          if (arg.length === 1) {
            return specialChars.includes(arg)
              ? `\\${arg}`
              : arg === ' '
                ? '\\s'
                : arg;
          } else {
            return arg
              .split('')
              .map((char) =>
                specialChars.includes(char)
                  ? `\\${char}`
                  : char === ' '
                    ? '\\s'
                    : char,
              )
              .join('');
          }
        };

        // 如果有参数，按参数进行 trim
        if (arg !== undefined) {
          const escapedArg = escapeSpecialChars(arg);
          const regex = new RegExp(`(^${escapedArg}*)|(${escapedArg}*$)`, 'g');
          return this.replace(regex, '');
        } else {
          // 如果没有参数，默认去除空白字符
          return this.replace(/(^\s*)|(\s*$)/g, '');
        }
      };
    }
  }

  // 初始化函数
  kiko.init = function (options = {}) {
    // 合并配置
    Object.assign(kiko.config, options);

    // 检查Tailwind CSS
    if (!kiko.core.utils.isTailwindAvailable()) {
      kiko.core.log(
        '警告: 未检测到Tailwind CSS，UI组件可能无法正常显示',
        null,
        'warn',
      );
    }

    // 初始化各组件
    for (const module in kiko.ui) {
      if (kiko.ui[module].init && typeof kiko.ui[module].init === 'function') {
        try {
          kiko.ui[module].init();
        } catch (e) {
          kiko.core.log(`初始化模块 ${module} 出错: ${e.message}`, e, 'error');
        }
      }
    }

    kiko.core.log('Kiko UI 初始化完成', { version: kiko.version });

    return kiko; // 支持链式调用
  };

  // 导出到全局
  window.kiko = kiko;
})(window, jQuery);


// ---- i18n/i18n.js ----
(function (kiko) {
  // 私有变量
  let currentLang = 'en'; // 默认语言为英文
  let apiSetLang = null; // 通过API设置的语言
  const messages = {}; // 存储所有语言的消息

  // 私有方法：检测浏览器语言
  const detectBrowserLang = function () {
    const browserLang = (
      navigator.language ||
      navigator.userLanguage ||
      'en'
    ).toLowerCase();
    // 处理中文地区的不同变体
    if (browserLang.startsWith('zh')) {
      if (browserLang.includes('tw') || browserLang.includes('hk')) {
        return 'zh-tw';
      } else {
        return 'zh-cn';
      }
    }
    // 对于其他语言，只返回主要部分 (例如 "en-US" -> "en")
    return browserLang.split('-')[0];
  };

  // 初始化模块
  const init = function () {
    // 优先顺序（从低到高）：
    // 1. 浏览器语言设置（自动感知）
    // 2. 通过kiko API设置的语言（使用setLang方法）
    // 3. 全局变量 window.kikoLang（优先级最高）

    // 首先获取浏览器语言
    let langToUse = detectBrowserLang();

    // 如果通过API设置了语言，优先使用API设置的语言
    if (apiSetLang) {
      langToUse = apiSetLang;
    }

    // 如果设置了全局变量，则使用全局变量（最高优先级）
    if (window.kikoLang && typeof window.kikoLang === 'string') {
      langToUse = window.kikoLang.toLowerCase();
    }

    // 设置当前语言
    currentLang = langToUse;

    // 如果设置的语言不存在，回退到英文
    if (!messages[currentLang]) {
      if (currentLang.includes('-')) {
        // 尝试只使用主要部分 (例如 "en-US" -> "en")
        currentLang = currentLang.split('-')[0];
        if (!messages[currentLang]) {
          currentLang = 'en';
        }
      } else {
        currentLang = 'en';
      }
    }

    kiko.core.log('i18n初始化完成，当前语言: ' + currentLang);
  };

  // 导出公共方法和属性
  kiko.i18n = {
    /**
     * 添加语言消息
     * @param {string} lang - 语言代码
     * @param {Object} msgs - 消息对象
     */
    addMessages: function (lang, msgs) {
      if (!messages[lang]) {
        messages[lang] = {};
      }
      // 合并消息
      Object.assign(messages[lang], msgs);
    },

    /**
     * 获取消息
     * @param {string} key - 消息键
     * @param {Object} [params] - 替换参数
     * @returns {string} 本地化的消息
     */
    getMessage: function (key, params) {
      // 查找当前语言的消息
      const msg = messages[currentLang] && messages[currentLang][key];

      // 如果找不到消息，尝试回退到英文
      const fallbackMsg =
        currentLang !== 'en' && messages['en'] ? messages['en'][key] : null;

      // 如果都找不到，返回键名
      const result = msg || fallbackMsg || key;

      // 如果有参数需要替换
      if (params && typeof result === 'string') {
        return result.replace(/\{([^}]+)\}/g, function (match, paramName) {
          return params[paramName] !== undefined ? params[paramName] : match;
        });
      }

      return result;
    },

    /**
     * 获取当前语言
     * @returns {string} 当前语言代码
     */
    getCurrentLang: function () {
      return currentLang;
    },

    /**
     * 设置当前语言
     * @param {string} lang - 语言代码
     * @returns {boolean} 是否设置成功
     */
    setLang: function (lang) {
      if (lang && messages[lang]) {
        currentLang = lang;
        // 保存API设置的语言
        apiSetLang = lang;

        // 触发语言变更事件
        if (typeof window.CustomEvent === 'function') {
          const event = new CustomEvent('kikoLangChange', {
            detail: { lang: currentLang },
          });
          document.dispatchEvent(event);
        }
        return true;
      }
      return false;
    },

    /**
     * 初始化i18n模块
     */
    init: init,
  };
})((window.kiko = window.kiko || {}));


// ---- ui/notify.js ----
(function ($, kiko) {
  'use strict';

  // 确保kiko.ui命名空间存在
  kiko = kiko || {};
  kiko.ui = kiko.ui || {};

  /**
   * 活动AJAX请求计数
   * @private
   * @type {number}
   */
  let activeRequests = 0;

  /**
   * 通知组件
   * @namespace
   */
  const Notify = {
    /**
     * 默认配置
     * @private
     * @type {Object}
     * @property {string} messageContainer - 消息容器选择器
     * @property {string} loadingIndicator - 加载指示器选择器
     * @property {number} successDuration - 成功消息显示时间（毫秒）
     * @property {number} warningDuration - 警告消息显示时间（毫秒）
     * @property {number} errorDuration - 错误消息显示时间（毫秒）
     * @property {string} position - 消息显示位置
     * @property {boolean} lazyInit - 是否延迟初始化DOM元素（仅在首次使用时创建）
     */
    config: {
      // 容器选择器
      messageContainer: '#kiko-message-container',
      loadingIndicator: '#kiko-loading-indicator',

      // 持续时间（毫秒）
      successDuration: 3000,
      warningDuration: 4000,
      errorDuration: 5000,

      // 消息位置
      position: 'top', // 'top', 'bottom', 'top-right', 'bottom-right', 'top-left', 'bottom-left'

      // 延迟初始化（仅在首次使用时创建DOM元素）
      lazyInit: true,
    },

    /**
     * 缓存的DOM引用
     * @private
     */
    _dom: {
      messageContainer: null,
      loadingIndicator: null,
    },

    /**
     * 初始化通知组件
     *
     * @param {Object} options - 配置选项
     * @param {string} [options.messageContainer] - 消息容器选择器
     * @param {string} [options.loadingIndicator] - 加载指示器选择器
     * @param {number} [options.successDuration] - 成功消息显示时间（毫秒）
     * @param {number} [options.warningDuration] - 警告消息显示时间（毫秒）
     * @param {number} [options.errorDuration] - 错误消息显示时间（毫秒）
     * @param {string} [options.position] - 消息显示位置
     * @param {boolean} [options.lazyInit] - 是否延迟初始化DOM元素
     * @returns {Object} 通知组件实例，支持链式调用
     *
     * @example
     * // 基本初始化
     * kiko.ui.notify.init();
     *
     * @example
     * // 自定义配置初始化
     * kiko.ui.notify.init({
     *   position: 'top-right',
     *   successDuration: 5000
     * });
     */
    init: function (options) {
      // 合并配置
      this.config = $.extend(this.config, options);

      // 如果不使用延迟初始化，立即创建DOM元素
      if (!this.config.lazyInit) {
        this._createElements();
      }

      return this;
    },

    /**
     * 确保必要的DOM元素已创建
     * @private
     * @returns {Object} 通知组件实例，支持链式调用
     */
    _ensureElements: function () {
      // 如果元素尚未创建，创建它们
      if (!this._dom.messageContainer || !this._dom.loadingIndicator) {
        this._createElements();
      }
      return this;
    },

    /**
     * 创建必要的DOM元素
     * @private
     * @returns {Object} 通知组件实例，支持链式调用
     */
    _createElements: function () {
      // 创建消息容器
      if (!this._dom.messageContainer) {
        const $container = $(this.config.messageContainer);
        if ($container.length === 0) {
          // 根据位置设置不同的样式
          let positionClass = 'fixed top-0 left-0 right-0';

          switch (this.config.position) {
            case 'bottom':
              positionClass = 'fixed bottom-0 left-0 right-0';
              break;
            case 'top-right':
              positionClass = 'fixed top-4 right-4 left-auto';
              break;
            case 'bottom-right':
              positionClass = 'fixed bottom-4 right-4 left-auto';
              break;
            case 'top-left':
              positionClass = 'fixed top-4 left-4 right-auto';
              break;
            case 'bottom-left':
              positionClass = 'fixed bottom-4 left-4 right-auto';
              break;
          }

          const messageContainerId = this.config.messageContainer.replace(
            '#',
            '',
          );
          $('body').append(
            `<div id="${messageContainerId}" class="${positionClass} z-50 p-4" style="display:none;"></div>`,
          );
          this._dom.messageContainer = $(this.config.messageContainer);
        } else {
          this._dom.messageContainer = $container;
        }
      }

      // 创建加载指示器
      if (!this._dom.loadingIndicator) {
        const $indicator = $(this.config.loadingIndicator);
        if ($indicator.length === 0) {
          const loadingIndicatorId = this.config.loadingIndicator.replace(
            '#',
            '',
          );
          $('body').append(
            `<div id="${loadingIndicatorId}" class="fixed top-4 right-4 z-50 bg-blue-100 border-blue-500 text-blue-700 p-2 rounded-full shadow-md flex items-center" style="display:none;">
              <svg class="animate-spin -ml-1 mr-2 h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <span>${this._getMessage('loading')}</span>
            </div>`,
          );
          this._dom.loadingIndicator = $(this.config.loadingIndicator);
        } else {
          this._dom.loadingIndicator = $indicator;
        }
      }

      return this;
    },

    /**
     * 获取i18n消息
     *
     * @private
     * @param {string} key - 消息键名
     * @param {Object} [params] - 替换参数
     * @returns {string} 本地化后的消息
     */
    _getMessage: function (key, params) {
      // 如果kiko有i18n能力，优先使用
      if (kiko.i18n && typeof kiko.i18n.getMessage === 'function') {
        return kiko.i18n.getMessage(key, params);
      }

      // 全局i18n对象
      if (window.appI18n && typeof window.appI18n.getMessage === 'function') {
        return window.appI18n.getMessage(key, params);
      }

      // 如果没有i18n支持，直接返回键名
      return key;
    },

    /**
     * 显示消息
     *
     * @param {string} message - 消息内容
     * @param {string} [type='error'] - 消息类型 ('success', 'warning', 'error')
     * @param {number} [timeout=3000] - 自动关闭时间（毫秒），设为0则不自动关闭
     * @returns {Object} 通知组件实例，支持链式调用
     *
     * @example
     * // 显示错误消息
     * kiko.ui.notify.show('操作失败，请重试', 'error');
     *
     * @example
     * // 显示警告消息，并设置显示时间
     * kiko.ui.notify.show('操作可能未完成', 'warning', 5000);
     */
    show: function (message, type = 'error', timeout = 3000) {
      // 确保DOM元素已创建
      this._ensureElements();

      let cssClass = '';
      let icon = '';

      switch (type) {
        case 'success':
          cssClass = 'bg-green-100 border-green-500 text-green-700';
          icon =
            '<svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path></svg>';
          break;
        case 'warning':
          cssClass = 'bg-yellow-100 border-yellow-500 text-yellow-700';
          icon =
            '<svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clip-rule="evenodd"></path></svg>';
          break;
        case 'error':
        default:
          cssClass = 'bg-red-100 border-red-500 text-red-700';
          icon =
            '<svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clip-rule="evenodd"></path></svg>';
          break;
      }

      const $message = $(`
        <div class="border-l-4 p-4 mb-2 flex items-center justify-between ${cssClass} animate-fadeIn rounded shadow-sm">
          <div class="flex items-center">
            ${icon}
            <span class="ml-3 message-content">${message}</span>
          </div>
          <button type="button" class="close-btn ml-auto">
            <svg class="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clip-rule="evenodd"></path></svg>
          </button>
        </div>
      `);

      // 绑定关闭按钮
      $message.find('.close-btn').on('click', function () {
        $message.fadeOut(300, function () {
          $(this).remove();

          // 如果没有更多消息，隐藏容器
          if (Notify._dom.messageContainer.children().length === 0) {
            Notify._dom.messageContainer.hide();
          }
        });
      });

      // 添加到消息容器
      this._dom.messageContainer.append($message).show();

      // 自动消失
      if (timeout > 0) {
        setTimeout(() => {
          $message.fadeOut(300, function () {
            $(this).remove();

            // 如果没有更多消息，隐藏容器
            if (Notify._dom.messageContainer.children().length === 0) {
              Notify._dom.messageContainer.hide();
            }
          });
        }, timeout);
      }

      return this;
    },

    /**
     * 显示成功消息
     *
     * @param {string} [message] - 消息内容，默认使用i18n('notify.operation.success')
     * @param {number} [timeout] - 自动关闭时间（毫秒），默认使用config.successDuration
     * @returns {Object} 通知组件实例，支持链式调用
     *
     * @example
     * // 显示默认成功消息
     * kiko.ui.notify.success();
     *
     * @example
     * // 显示自定义成功消息
     * kiko.ui.notify.success('数据保存成功');
     */
    success: function (message, timeout) {
      return this.show(
        message || this._getMessage('notify.operation.success'),
        'success',
        timeout || this.config.successDuration,
      );
    },

    /**
     * 显示警告消息
     *
     * @param {string} message - 警告消息内容
     * @param {number} [timeout] - 自动关闭时间（毫秒），默认使用config.warningDuration
     * @returns {Object} 通知组件实例，支持链式调用
     *
     * @example
     * // 显示警告消息
     * kiko.ui.notify.warning('此操作可能需要较长时间');
     */
    warning: function (message, timeout) {
      return this.show(
        message,
        'warning',
        timeout || this.config.warningDuration,
      );
    },

    /**
     * 显示错误消息
     *
     * @param {string} message - 错误消息内容
     * @param {number} [timeout] - 自动关闭时间（毫秒），默认使用config.errorDuration
     * @returns {Object} 通知组件实例，支持链式调用
     *
     * @example
     * // 显示错误消息
     * kiko.ui.notify.error('无法连接到服务器');
     */
    error: function (message, timeout) {
      return this.show(message, 'error', timeout || this.config.errorDuration);
    },

    /**
     * 显示或隐藏加载状态
     *
     * @param {boolean} show - 是否显示加载指示器
     * @returns {Object} 通知组件实例，支持链式调用
     *
     * @example
     * // 显示加载指示器
     * kiko.ui.notify.loading(true);
     *
     * @example
     * // 隐藏加载指示器
     * kiko.ui.notify.loading(false);
     */
    loading: function (show) {
      // 确保DOM元素已创建
      this._ensureElements();

      if (show) {
        activeRequests++;
        this._dom.loadingIndicator.fadeIn(200);
      } else {
        activeRequests = Math.max(0, activeRequests - 1);
        if (activeRequests === 0) {
          this._dom.loadingIndicator.fadeOut(200);
        }
      }

      return this;
    },
  };

  // 导出到kiko命名空间
  kiko.ui.notify = Notify;
})(jQuery, window.kiko || (window.kiko = {}));


// ---- ui/box.js ----
(function ($, kiko) {
  // 注意：多语言定义已移至 kiko/src/i18n/ 目录下的语言文件中

  // 私有变量
  let options = {};
  let idPrefix = 'kikobox-';
  let uniqueId = '';
  let resizeTimer = null;

  // 缓存的对话框实例，用于cache=true时重用DOM
  const cachedBoxes = {};

  // 生成一个随机ID后缀，确保多个实例不会冲突
  const generateUniqueId = function () {
    return kiko.core.dom.generateId('');
  };

  // 获取带前缀的元素ID
  const getId = function (elementName) {
    return idPrefix + elementName + uniqueId;
  };

  // 获取元素选择器
  const getSelector = function (elementName) {
    return '#' + getId(elementName);
  };

  /**
   * 缓存机制(cache=true)工作原理：
   *
   * 1. 当用户设置cache=true时，必须同时提供boxId参数
   * 2. 系统会检查boxId对应的对话框是否已存在于缓存中
   * 3. 如果已存在，则显示已缓存的对话框，不会创建新DOM
   * 4. 如果不存在，则创建新对话框并以boxId为键存入缓存
   * 5. 当关闭带缓存的对话框时，DOM不会被销毁，仅被隐藏
   */

  // 私有方法：初始化对话框
  const initBox = function (opts) {
    // 设置选项
    options = $.extend(
      {
        title: kiko.i18n.getMessage('box_title'),
        content: kiko.i18n.getMessage('box_content'),
        modal: true,
        position: 'center',
        width: 400,
        height: 300,
        idPrefix: 'kikobox-',
        responsive: true,
        smBreakpoint: 640,
        overlayOpacity: 0.5,
        cache: false, // 默认不缓存对话框DOM
      },
      opts || {},
    );

    // 如果提供了自定义前缀，则使用它
    if (options.idPrefix) {
      idPrefix = options.idPrefix;
    }

    // 缓存功能：检查是否启用缓存且提供了boxId
    if (options.cache) {
      // 当cache=true时必须提供boxId
      if (!options.boxId) {
        console.error('启用cache=true时必须提供唯一的boxId参数');
        options.cache = false; // 禁用缓存
      } else if (cachedBoxes[options.boxId]) {
        // 使用缓存的对话框ID
        uniqueId = options.boxId;

        // 显示缓存的对话框
        $('#' + idPrefix + 'outer-container' + uniqueId).removeClass('hidden');
        $('#' + idPrefix + 'overlay' + uniqueId).removeClass('hidden');

        // 重新绑定关闭按钮事件
        $('#' + idPrefix + 'close' + uniqueId)
          .off('click')
          .on('click', function () {
            methods.close();
          });

        // 如果提供了新标题，更新缓存的对话框标题
        if (
          options.title &&
          options.title !== kiko.i18n.getMessage('box_title')
        ) {
          $('#' + idPrefix + 'title' + uniqueId).text(options.title);
        }

        // 如果提供了新内容，更新缓存的对话框内容
        if (
          options.content &&
          options.content !== kiko.i18n.getMessage('box_content')
        ) {
          $('#' + idPrefix + 'content' + uniqueId).html(options.content);
        }

        // 直接返回，不再继续创建新对话框
        return;
      }
    }

    // 生成或使用对话框ID
    if (options.cache && options.boxId) {
      // 使用提供的boxId作为唯一ID
      uniqueId = options.boxId;
    } else {
      // 生成新的唯一ID
      uniqueId = generateUniqueId();
    }

    // 创建对话框DOM
    const boxHtml = `
      <div id="${getId('outer-container')}" class="hidden fixed inset-0 z-50 p-4 flex items-center justify-center">
        <div id="${getId('container')}" class="bg-white border-8 border-gray-200 shadow-lg overflow-hidden">
          <div id="${getId('header')}" class="flex justify-between items-center p-4 border-b border-gray-300">
            <div id="${getId('title')}" class="text-lg font-semibold"></div>
            <button id="${getId('close')}" class="text-gray-500 hover:text-gray-700 cursor-pointer" title="${kiko.i18n.getMessage('box_close')}">
              <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
          <div id="${getId('wrapper')}" class="p-4">
            <div id="${getId('content')}" class="overflow-auto"></div>
          </div>
          <div id="${getId('footer')}" class="p-4 border-t hidden"></div>
        </div>
      </div>
      <div id="${getId('overlay')}" class="hidden fixed inset-0 bg-black z-40" style="opacity: ${options.overlayOpacity}"></div>
    `;
    $(boxHtml).appendTo('body');

    // 添加窗口大小变化监听
    if (options.responsive) {
      $(window).on('resize', handleWindowResize);
    }

    // 如果启用了缓存，将当前对话框存入缓存
    if (options.cache && options.boxId) {
      cachedBoxes[options.boxId] = true;

      // 添加debug信息，帮助调试
      if (options.debug) {
        console.log('缓存对话框', options.boxId);
      }
    }

    // 设置事件和内容
    $(getSelector('close'))
      .off('click')
      .on('click', function () {
        methods.close();
      });
    $(getSelector('title')).text(options.title);

    // 设置底部文本
    if (typeof options.footerTxt === 'string') {
      $(getSelector('footer')).html(options.footerTxt).removeClass('hidden');
    } else {
      $(getSelector('footer')).addClass('hidden');
    }

    // 设置模态遮罩
    if (options.modal) {
      $(getSelector('overlay')).removeClass('hidden');
    } else {
      $(getSelector('overlay')).addClass('hidden');
    }

    // 加载内容
    if (typeof options.content === 'string') {
      $(getSelector('content')).html(options.content);
    } else if (typeof options.targetId === 'string') {
      $(getSelector('content')).html($('#' + options.targetId).html());
    } else if (typeof options.ajaxUrl === 'string') {
      $(getSelector('content')).html(
        `<div class="flex justify-center items-center h-full"><div class="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div><span class="ml-2">${kiko.i18n.getMessage('box_loading')}</span></div>`,
      );

      kiko.core.ajax({
        url: options.ajaxUrl,
        success: function (data) {
          $(getSelector('content')).html(data);
          if (typeof options.ajaxCallback === 'function') {
            options.ajaxCallback();
          }
        },
      });
    } else if (typeof options.iframeUrl === 'string') {
      $(getSelector('content')).html(
        `<iframe frameborder="0" class="w-full h-full" src="${options.iframeUrl}"></iframe>`,
      );
    }
  };

  // 私有方法：更新对话框位置和大小
  const updateBoxPosition = function () {
    const width = options.width;
    const height = options.height;
    const windowWidth =
      window.innerWidth ||
      document.documentElement.clientWidth ||
      document.body.clientWidth;
    const mdBreakpoint = 768; // MD断点
    const $outerContainer = $(getSelector('outer-container'));
    const $container = $(getSelector('container'));
    const $content = $(getSelector('content'));

    // 显示容器和遮罩层
    if (options.modal) {
      $(getSelector('overlay')).removeClass('hidden');
    }
    $outerContainer.removeClass('hidden');

    // 以MD尺寸为界
    if (windowWidth <= mdBreakpoint) {
      // 小于等于MD尺寸：采用统一的全屏带边距逻辑
      $container.css({
        width: 'calc(100% - 2rem)',
        height: 'calc(100% - 2rem)',
        maxWidth: '100%',
        maxHeight: '100%',
        margin: '0',
      });

      // 内容区域占满容器
      $content.css({
        height: '100%',
      });
    } else {
      // 大于MD尺寸：恢复初始状态
      $container.css({
        width: width + 'px',
        height: 'auto',
        maxWidth: '',
        maxHeight: '',
        margin: '0',
      });

      // 设置内容区域为用户指定高度
      $content.css({
        height: height + 'px',
      });
    }
  };

  // 窗口大小变化处理函数
  const handleWindowResize = function () {
    if (resizeTimer) {
      clearTimeout(resizeTimer);
    }
    resizeTimer = setTimeout(function () {
      // 只有当容器可见时才更新位置
      if (!$(getSelector('outer-container')).hasClass('hidden')) {
        updateBoxPosition();
      }
    }, 200);
  };

  // 私有方法：获取位置样式
  const getPositionStyles = function (
    horizontalPos,
    width,
    height,
    verticalPos = 'center',
  ) {
    const styles = {};
    const windowWidth =
      window.innerWidth ||
      document.documentElement.clientWidth ||
      document.body.clientWidth;
    const windowHeight =
      window.innerHeight ||
      document.documentElement.clientHeight ||
      document.body.clientHeight;

    // 边距设置，确保在中等屏幕及以上有足够边距
    const margin = 16; // 1rem = 16px

    // 计算可用空间，考虑边距
    const availableWidth = windowWidth - margin * 2;
    const availableHeight = windowHeight - margin * 2;

    // 调整宽高，确保不超出可用空间
    const adjustedWidth = Math.min(width, availableWidth);
    const adjustedHeight = Math.min(height, availableHeight);

    // 水平位置
    switch (horizontalPos) {
      case 'center':
        styles.left =
          Math.max(margin, Math.floor((windowWidth - adjustedWidth) / 2)) +
          'px';
        styles.right = 'auto';
        break;
      case 'left':
        styles.left = margin + 'px';
        styles.right = 'auto';
        break;
      case 'right':
        styles.right = margin + 'px';
        styles.left = 'auto';
        break;
      default:
        if (typeof horizontalPos === 'number') {
          styles.left = Math.max(margin, horizontalPos) + 'px';
          styles.right = 'auto';
        } else {
          styles.left =
            Math.max(margin, Math.floor((windowWidth - adjustedWidth) / 2)) +
            'px';
          styles.right = 'auto';
        }
        break;
    }

    // 垂直位置
    switch (verticalPos) {
      case 'center':
        styles.top =
          Math.max(margin, Math.floor((windowHeight - adjustedHeight) / 2)) +
          'px';
        styles.bottom = 'auto';
        break;
      case 'top':
        styles.top = margin + 'px';
        styles.bottom = 'auto';
        break;
      case 'bottom':
        styles.bottom = margin + 'px';
        styles.top = 'auto';
        break;
      default:
        if (typeof verticalPos === 'number') {
          styles.top = Math.max(margin, verticalPos) + 'px';
          styles.bottom = 'auto';
        } else {
          styles.top =
            Math.max(margin, Math.floor((windowHeight - adjustedHeight) / 2)) +
            'px';
          styles.bottom = 'auto';
        }
        break;
    }

    return styles;
  };

  /**
   * 添加按钮到对话框
   * @param {string} type - 对话框类型: 'dialog', 'confirm', 'message'
   * @param {Object} opts - 配置选项
   */
  const setupButtons = function (type, opts) {
    // 获取或创建按钮容器
    let $buttonsContainer = $(getSelector('buttons'));

    // 按钮位置：默认为right, 可选left, center, right
    const buttonAlign = opts.buttonAlign || 'right';

    // 根据位置设置对应的Tailwind类
    const alignClass =
      {
        left: 'justify-start',
        center: 'justify-center',
        right: 'justify-end',
      }[buttonAlign] || 'justify-end';

    // 如果按钮容器不存在则创建
    if ($buttonsContainer.length === 0) {
      $(getSelector('wrapper')).after(`
        <div id="${getId('buttons')}" class="flex ${alignClass} space-x-4 p-4 border-t border-gray-300">
        </div>
      `);
      $buttonsContainer = $(getSelector('buttons'));
    } else {
      // 清空现有按钮并更新对齐方式
      $buttonsContainer
        .empty()
        .removeClass('justify-start justify-center justify-end')
        .addClass(alignClass);
    }

    // 按钮配置 - 不同类型对话框的默认按钮配置
    const buttonConfig = {
      dialog: {
        showOk: opts.showOkButton === true ? true : false,
        showCancel: opts.showCancelButton === true ? true : false,
      },
      confirm: {
        showOk: true,
        showCancel: true,
      },
      message: {
        showOk: true,
        showCancel: false,
      },
    };

    // 检查是否需要显示按钮
    const hasAnyButtons =
      buttonConfig[type].showOk || buttonConfig[type].showCancel;

    // 如果没有按钮要显示，隐藏按钮容器并返回
    if (!hasAnyButtons) {
      $buttonsContainer.addClass('hidden');
      return;
    } else {
      $buttonsContainer.removeClass('hidden');
    }

    // 确定按钮文本 - 优先使用自定义文本，否则使用国际化消息
    const okText = opts.okButtonText || kiko.i18n.getMessage('box_ok');

    // 取消按钮文本 - 优先使用自定义文本，否则使用国际化消息
    const cancelText =
      opts.cancelButtonText || kiko.i18n.getMessage('box_cancel');

    // 添加确认按钮
    if (buttonConfig[type].showOk) {
      // 支持自定义确认按钮样式类
      const okButtonClass =
        opts.okButtonClass ||
        'px-4 py-2 bg-blue-500 text-white hover:bg-blue-600 transition-colors duration-200';

      const $okButton = $(`
        <button id="${getId('ok')}" class="${okButtonClass}">${okText}</button>
      `);

      // 绑定点击事件
      $okButton.on('click', function () {
        let shouldClose = true;
        if (typeof opts.onOk === 'function') {
          const result = opts.onOk();
          shouldClose = result !== false; // 如果回调返回false，则不关闭对话框
        }
        if (shouldClose) {
          methods.close();
        }
      });

      $buttonsContainer.append($okButton);
    }

    // 添加取消按钮
    if (buttonConfig[type].showCancel) {
      // 支持自定义取消按钮样式类
      const cancelButtonClass =
        opts.cancelButtonClass ||
        'px-4 py-2 bg-gray-300 text-gray-700 hover:bg-gray-400 transition-colors duration-200';

      const $cancelButton = $(`
        <button id="${getId('cancel')}" class="${cancelButtonClass}">${cancelText}</button>
      `);

      // 绑定点击事件
      $cancelButton.on('click', function () {
        methods.close();
        if (typeof opts.onCancel === 'function') {
          opts.onCancel();
        }
      });

      $buttonsContainer.append($cancelButton);
    }
  };

  // 公共方法集合
  const methods = {
    /**
     * 显示对话框
     * @param {Object} opts - 配置选项
     */
    dialog: function (opts) {
      if (typeof opts.onBeforeOpen === 'function') {
        opts.onBeforeOpen();
      }

      // 启用调试模式
      if (opts.debug) {
        opts.debug = true;
      }

      // 如果没有指定触发元素，尝试从jQuery.event中获取
      if (!opts.triggerElement && $.event && $.event.triggered) {
        opts.triggerElement = $.event.triggered.target;
      }

      initBox(opts);

      // 设置对话框按钮
      setupButtons('dialog', opts);

      updateBoxPosition();

      if (typeof options.onOpen === 'function') {
        options.onOpen();
      }

      // 返回生成的唯一ID，以便外部引用
      return uniqueId;
    },

    /**
     * 显示确认对话框
     * @param {Object} opts - 配置选项
     */
    confirm: function (opts) {
      if (typeof opts.onBeforeOpen === 'function') {
        opts.onBeforeOpen();
      }

      initBox(opts);

      // 设置确认对话框按钮
      setupButtons('confirm', opts);

      updateBoxPosition();

      if (typeof options.onOpen === 'function') {
        options.onOpen();
      }

      // 返回生成的唯一ID，以便外部引用
      return uniqueId;
    },

    /**
     * 显示消息对话框
     * @param {Object} opts - 配置选项
     */
    message: function (opts) {
      if (typeof opts.onBeforeOpen === 'function') {
        opts.onBeforeOpen();
      }

      initBox(opts);

      // 设置消息对话框按钮
      setupButtons('message', opts);

      updateBoxPosition();

      if (typeof options.onOpen === 'function') {
        options.onOpen();
      }

      // 返回生成的唯一ID，以便外部引用
      return uniqueId;
    },

    /**
     * 关闭对话框
     * @param {string} id - 可选的指定实例ID，如果不提供则关闭当前实例
     */
    close: function (id) {
      // 如果提供了ID，则设置该ID为当前ID
      if (id) {
        uniqueId = id;
      }

      if (typeof options.onBeforeClose === 'function') {
        options.onBeforeClose();
      }

      // 同时隐藏容器和遮罩层
      $(getSelector('outer-container')).addClass('hidden');
      $(getSelector('overlay')).addClass('hidden');

      // 决定是清空内容还是完全删除DOM
      if (!options.cache) {
        // 如果不缓存，则删除DOM元素
        $(getSelector('outer-container')).remove();
        $(getSelector('overlay')).remove();

        // 从缓存中移除
        if (options.boxId && cachedBoxes[options.boxId]) {
          delete cachedBoxes[options.boxId];
        }

        // 解除窗口大小变化监听
        if (options.responsive) {
          $(window).off('resize', handleWindowResize);
        }
      } else {
        // 如果缓存，只清空按钮
        $(getSelector('buttons')).empty();
      }

      if (typeof options.onClose === 'function') {
        options.onClose();
      }
    },

    /**
     * 获取当前对话框实例的唯一ID
     * @returns {string} 当前对话框的唯一ID
     */
    getId: function () {
      return uniqueId;
    },

    /**
     * 设置默认ID前缀
     * @param {string} prefix - 新的ID前缀
     */
    setIdPrefix: function (prefix) {
      if (typeof prefix === 'string' && prefix) {
        idPrefix = prefix;
      }
    },

    /**
     * 清除所有缓存的对话框DOM
     *
     * 当使用cache=true创建了大量对话框并需要释放内存时，
     * 或者当对话框的内容结构发生了变化需要强制重建时，
     * 可以调用此方法清除所有缓存
     */
    clearCache: function () {
      // 遍历所有缓存的对话框，删除DOM
      for (const id in cachedBoxes) {
        if (cachedBoxes.hasOwnProperty(id)) {
          // 临时设置uniqueId以便获取正确的选择器
          const oldId = uniqueId;
          uniqueId = id;

          // 删除DOM
          $(getSelector('outer-container')).remove();
          $(getSelector('overlay')).remove();

          // 恢复uniqueId
          uniqueId = oldId;
        }
      }

      // 清空缓存对象
      Object.keys(cachedBoxes).forEach((key) => {
        delete cachedBoxes[key];
      });
    },

    /**
     * 清除特定ID的缓存对话框
     * @param {string} id - 要清除的对话框ID
     */
    clearCacheById: function (id) {
      if (!id || !cachedBoxes[id]) {
        return;
      }

      // 临时设置uniqueId以便获取正确的选择器
      const oldId = uniqueId;
      uniqueId = id;

      // 删除DOM
      $(getSelector('outer-container')).remove();
      $(getSelector('overlay')).remove();

      // 从缓存中移除
      delete cachedBoxes[id];

      // 恢复uniqueId
      uniqueId = oldId;
    },
  };

  // 在Kiko命名空间中注册box组件
  kiko.ui.box = {
    /**
     * 初始化box组件
     */
    init: function () {
      kiko.core.log('正在初始化对话框组件...');
    },

    /**
     * 显示对话框
     * @param {Object} options - 配置选项
     * @returns {string} 对话框实例ID
     */
    dialog: function (options) {
      return methods.dialog(options);
    },

    /**
     * 显示确认对话框
     * @param {Object} options - 配置选项
     * @returns {string} 对话框实例ID
     */
    confirm: function (options) {
      return methods.confirm(options);
    },

    /**
     * 显示消息对话框
     * @param {Object} options - 配置选项
     * @returns {string} 对话框实例ID
     */
    message: function (options) {
      return methods.message(options);
    },

    /**
     * 关闭对话框
     * @param {string} id - 可选的对话框实例ID
     */
    close: methods.close,

    /**
     * 获取当前对话框实例ID
     * @returns {string} 当前对话框实例ID
     */
    getId: methods.getId,

    /**
     * 设置默认ID前缀
     * @param {string} prefix - 新的ID前缀
     */
    setIdPrefix: methods.setIdPrefix,

    /**
     * 清除所有缓存的对话框DOM
     */
    clearCache: methods.clearCache,

    /**
     * 清除特定ID的缓存对话框
     * @param {string} id - 要清除的对话框ID
     */
    clearCacheById: methods.clearCacheById,
  };

  // 导出到 jQuery 命名空间
  $.box = {
    dialog: function (options) {
      return methods.dialog(options);
    },
    confirm: function (options) {
      return methods.confirm(options);
    },
    message: function (options) {
      return methods.message(options);
    },
    close: methods.close,
    getId: methods.getId,
    setIdPrefix: methods.setIdPrefix,
    clearCache: methods.clearCache,
    clearCacheById: methods.clearCacheById,
  };

  // 提供jQuery插件方法
  $.fn.kikoBox = function (options) {
    options = options || {};

    if (this.length > 0) {
      options.targetId = this.attr('id');

      // 使用第一个元素作为触发元素，直接传递给options
      options.triggerElement = this[0];

      // 保留旧的方式设置 window.event 作为兼容
      const e = { currentTarget: this[0] };
      window.event = e;

      return methods.dialog(options);
    }

    return methods.dialog(options);
  };
})(jQuery, kiko);


// ---- ui/grid.js ----
(function ($, kiko) {
  // 私有函数：替换参数占位符的函数
  const replaceParam = function (text, value) {
    return value.reduce((result, val, i) => {
      const reg = new RegExp(`{(${i})}`, 'g');
      return result.replace(reg, val);
    }, text);
  };

  // 私有函数：从数组中获取值的函数
  const getValueFromAry = function (ary, value) {
    return value.map((val) => {
      let temp = ary[val.pos || val] || val.def || '';
      temp = temp.toString();

      if (val.parse && val.parse[temp]) {
        temp = val.parse[temp];
      }

      if (val.func) {
        temp = eval(val.func)(temp);
      }

      if (val.maxlen) {
        temp = truncate(temp, val.maxlen, '...');
      }

      // 这里改为使用kiko的HTML编码函数，如果core中有提供的话
      if (!val.isHtml) {
        temp = htmlEncode(temp);
      }

      return temp;
    });
  };

  // 私有函数：截断字符串的函数
  const truncate = function (val, num, suffix) {
    if (val.replace(/[^\x00-\xff]/g, '**').length <= num) {
      return val;
    }
    let bytenum = 0;
    let rs = '';
    const pt = /[^\x00-\xff]/;
    num -= suffix.length;

    for (let i = 0; i < num; i++) {
      const ch = val.substr(i, 1);
      bytenum += ch.match(pt) ? 2 : 1;
      if (bytenum > num) break;
      rs += ch;
    }

    return rs + suffix;
  };

  // 私有函数：HTML编码函数
  const htmlEncode = function (str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  };

  // 公共方法
  const methods = {
    /**
     * 创建表格
     * @param {Object} options - 表格配置选项
     * @returns {jQuery} jQuery对象，支持链式调用
     */
    create: function (element, options) {
      const $element = $(element);

      // 初始化 HTML 数组
      const aryHtml = [];

      // 添加表格的起始标签
      aryHtml.push(`<table id="${options.id}" class="${options.className}">`);

      // 如果有表格标题，则添加标题
      if (options.caption) {
        aryHtml.push(`<caption>${options.caption}</caption>`);
      }

      // 如果有表头模板，则添加表头
      if (options.template.head) {
        aryHtml.push('<thead><tr>');
        options.template.head.forEach((head) => {
          // 获取表头文本
          const title = head.text || head;
          aryHtml.push(`<td>${title}</td>`);
        });
        aryHtml.push('</tr></thead>');
      }

      // 添加表格主体的起始标签
      aryHtml.push('<tbody>');
      const tempRow = options.template.row;
      const ds = options.ds;

      // 如果数据源为空，则添加无数据提示
      if (ds.length === 0) {
        aryHtml.push(
          `<tr><td>${options.noData || kiko.i18n.getMessage('grid_no_data')}</td></tr>`,
        );
      } else {
        // 遍历数据源，生成表格行
        ds.forEach((data, i) => {
          // 每列数目达到指定值时，换行
          if (i % options.col === 0) {
            if (i !== 0) aryHtml.push('</tr>');
            aryHtml.push('<tr');

            // 如果有行样式，则添加样式
            if (tempRow.className) {
              let temp = tempRow.className;
              // 如果有交替行样式，则应用交替样式
              if (tempRow.switchClassName && i % 2 !== 0) {
                temp = tempRow.switchClassName;
              }
              aryHtml.push(` class="${temp}"`);
            }

            // 如果有行标记，则添加标记
            if (tempRow.mark) {
              aryHtml.push(` ${tempRow.mark}`);
            }

            // 如果有行事件，则添加事件
            if (tempRow.event) {
              tempRow.event.forEach((event) => {
                aryHtml.push(` ${event.name}="${event.func}"`);
              });
            }

            aryHtml.push('>');
          }

          const tempCell = options.template.cell;
          let cellMark = '';

          // 如果有单元格属性，则添加单元格事件
          if (options.template.cellAttr && options.template.cellAttr.event) {
            options.template.cellAttr.event.forEach((event) => {
              cellMark += ` ${event.name}="${event.func}"`;
            });
          }

          // 遍历单元格模板，生成单元格
          tempCell.forEach((cell) => {
            aryHtml.push(`<td ${cellMark}`);
            if (cell.className) {
              aryHtml.push(` class="${cell.className}"`);
            }
            aryHtml.push(
              `>${replaceParam(cell.text, getValueFromAry(data, cell.value))}</td>`,
            );
          });
        });
      }

      // 结束表格主体标签
      aryHtml.push('</tr></tbody>');

      // 如果有表尾模板且数据源不为空，则添加表尾
      if (options.template.foot && ds.length !== 0) {
        aryHtml.push(
          `<tfoot><tr><td colspan="${options.template.cell.length * options.col}">`,
        );
        let temp = options.template.foot.text;
        if (options.pageLink) {
          temp = temp.replace(
            '{0}',
            `<div class="kikonav">${options.pageLink}</div>`,
          );
        }
        aryHtml.push(`<div class="pages">${temp}</div>`);
        aryHtml.push(
          `<input type="hidden" name="${options.id}ViewState" id="${options.id}ViewState}" />`,
        );
        aryHtml.push('</td></tr></tfoot>');
      }

      // 结束表格标签
      aryHtml.push('</table>');

      // 将生成的 HTML 设置到容器中
      $element.html(aryHtml.join(''));

      return $element;
    },

    /**
     * 初始化模块
     */
    init: function () {
      kiko.core.log('初始化表格组件');

      // 注册$.fn.kikoGrid方法，兼容jQuery链式调用
      $.fn.kikoGrid = function (options) {
        return methods.create(this, options);
      };
    },
  };

  // 导出到kiko命名空间
  kiko.ui.grid = methods;
})(jQuery, window.kiko);


// ---- ui/tab.js ----
(function ($, kiko) {
  // 私有变量
  let idPrefix = 'kikotab-';
  let settings = {
    activeClass: 'text-blue-600 border-b-2 border-blue-500',
    inactiveClass: 'text-gray-500 hover:text-gray-700',
    baseTabClass: 'px-4 py-2 transition-colors duration-150',
  };

  // 获取URL锚点值
  const getAnchor = function () {
    return window.location.hash ? window.location.hash.substring(1) : '';
  };

  // 生成一个随机ID后缀，确保多个实例不会冲突
  const generateUniqueId = function () {
    return kiko.core.dom.generateId('');
  };

  // 私有方法集合
  const internal = {
    /**
     * 处理标签点击事件
     * @param {Event} e - 事件对象
     */
    handleTabClick: function (e) {
      e.preventDefault();

      const $target = $(this);
      const tabGroup = $target.attr('tabgroup');
      const tabTarget = $target.attr('tabtarget');

      if (!tabGroup || !tabTarget) return;

      // 切换到目标标签
      methods.switchTo(tabGroup, tabTarget);

      // 更新URL哈希以支持导航
      if ($target.attr('rel')) {
        window.location.hash = $target.attr('rel');
      }
    },

    /**
     * 初始化标签样式
     * @param {jQuery} $tab - 标签元素
     */
    setupTabStyles: function ($tab) {
      // 如果标签还没有基础样式类，添加它
      if (!$tab.hasClass(settings.baseTabClass)) {
        $tab.addClass(settings.baseTabClass);
      }

      // 默认添加非激活样式
      if (!$tab.hasClass('current')) {
        $tab.addClass(settings.inactiveClass);
      } else {
        $tab.addClass(settings.activeClass);
      }
    },
  };

  // 公共方法集合
  const methods = {
    /**
     * 初始化选项卡系统
     * @param {Object} options - 配置选项
     * @returns {Object} tab实例，支持链式调用
     */
    init: function (options) {
      // 合并设置
      if (options) {
        settings = $.extend(settings, options);
      }

      kiko.core.log('初始化选项卡组件');

      // 获取URL锚点
      const anchor = getAnchor();

      // 查找并初始化所有未加载的选项卡
      $('a[tabgroup][loadedtab!=true]').each(function (i, el) {
        const $tab = $(el);

        // 绑定点击事件
        $tab.on('click', internal.handleTabClick);

        // 设置基础样式
        internal.setupTabStyles($tab);

        // 如果有锚点匹配，激活该标签
        if ($tab.attr('rel') === anchor && anchor.length > 0) {
          $(`a[tabgroup="${$tab.attr('tabgroup')}"]`)
            .removeClass('current ' + settings.activeClass)
            .addClass(settings.inactiveClass);
          $tab
            .addClass('current ' + settings.activeClass)
            .removeClass(settings.inactiveClass);

          // 也显示对应的内容
          if ($tab.attr('tabtarget')) {
            methods.switchTo(
              $tab.attr('tabgroup'),
              $tab.attr('tabtarget'),
              false,
            );
          }
        }

        // 标记为已加载
        $tab.attr('loadedtab', 'true');
      });

      // 美化标签容器
      $('div:has(a[tabgroup])')
        .not('.tab-styled')
        .each(function () {
          $(this).addClass('flex border-b space-x-2 mb-4 tab-styled');
        });

      return this;
    },

    /**
     * 切换到指定标签
     * @param {string} tabGroup - 标签组名称
     * @param {string} targetId - 目标内容区域ID
     * @param {boolean} updateTabs - 是否更新标签状态，默认为true
     * @returns {Object} tab实例，支持链式调用
     */
    switchTo: function (tabGroup, targetId, updateTabs = true) {
      // 如果需要更新标签状态
      if (updateTabs) {
        // 移除所有同组标签的激活状态
        $(`a[tabgroup="${tabGroup}"]`)
          .removeClass('current ' + settings.activeClass)
          .addClass(settings.inactiveClass);

        // 激活目标标签
        $(`a[tabgroup="${tabGroup}"][tabtarget="${targetId}"]`)
          .addClass('current ' + settings.activeClass)
          .removeClass(settings.inactiveClass);
      }

      // 处理内容区域的显示/隐藏
      $(`a[tabgroup="${tabGroup}"][tabtarget]`).each(function () {
        const $tab = $(this);
        const $content = $(`#${$tab.attr('tabtarget')}`);

        if ($tab.attr('tabtarget') === targetId) {
          $content.removeClass('hidden').show();
        } else {
          $content.addClass('hidden').hide();
        }
      });

      return this;
    },

    /**
     * 设置选项卡系统选项
     * @param {Object} options - 配置选项
     * @returns {Object} tab实例，支持链式调用
     */
    setOptions: function (options) {
      settings = $.extend(settings, options);
      return this;
    },

    /**
     * 刷新所有标签样式
     * @returns {Object} tab实例，支持链式调用
     */
    refreshStyles: function () {
      $('a[tabgroup][loadedtab=true]').each(function () {
        const $tab = $(this);
        internal.setupTabStyles($tab);
      });
      return this;
    },
  };

  // 导出到kiko命名空间
  kiko.ui.tab = methods;
})(jQuery, window.kiko);


// ---- ui/pager.js ----
(function ($, kiko) {
  // 确保kiko.ui命名空间存在
  kiko = kiko || {};
  kiko.ui = kiko.ui || {};

  /**
   * 页面行为管理器
   */
  const PageAction = {
    /**
     * 配置项
     * @private
     *
     * 可用配置项:
     * - defaultSelector {String} 默认的行为选择器，默认为'[data-action]'
     * - enableAnchorCapture {Boolean} 是否启用锚点拦截，默认为true
     * - defaultEvent {String} 默认事件类型，默认为'click'
     * - targetAttribute {String} 指定目标的属性名，默认为'data-target'
     * - cache {Boolean} 是否缓存URL请求内容，默认为false
     * - debug {Boolean} 是否启用调试模式，默认为false
     * - loadingText {String} 加载提示文本，默认为'正在加载...'
     * - dataAttributePrefix {String} 数据属性前缀，默认为'data-'
     * - errorHandler {Function} 错误处理函数，接收(error, type, data)参数
     * - init {Function} 初始化函数，在每个行为执行前调用，返回false可阻止执行
     * - complete {Function} 完成函数，在每个行为执行后调用，无论成功失败
     */
    config: {
      // 默认选择器（使用data-action属性的元素）
      defaultSelector: '[data-action]',
      // 是否启用锚点拦截
      enableAnchorCapture: true,
      // 默认事件类型
      defaultEvent: 'click',
      // 默认目标属性名
      targetAttribute: 'data-target',
      // 是否缓存URL请求内容
      cache: false,
      // 是否启用调试模式
      debug: false,
      // 加载提示文本
      loadingText: '正在加载...',
      // 数据属性前缀，用于收集DOM元素上的data-*属性
      dataAttributePrefix: 'data-',
      // 错误处理函数
      errorHandler: function (error, type, data) {
        console.error('[PageAction Error]', error, type, data);
      },
      // 初始化函数，在每个页面行为执行前调用
      init: function (action, data) {
        // 默认不执行任何操作
        return true;
      },
      // 完成函数，在每个页面行为执行后调用
      complete: function (success, action, data) {
        // 默认不执行任何操作
      },
    },

    /**
     * 行为配置存储
     * @private
     */
    actions: {},

    /**
     * 响应缓存
     * @private
     */
    cache: {},

    /**
     * 初始化页面行为管理器
     *
     * 初始化组件并注册行为配置，支持两种形式的行为配置：
     * 1. 数组形式: [{id: 'action1', ...}, {id: 'action2', ...}]
     * 2. 对象形式: {'action1': {...}, 'action2': {...}}
     *
     * @param {Object} options - 配置选项，见config说明
     * @param {Array|Object} actions - 行为配置数组或对象
     * @returns {Object} PageAction实例，支持链式调用
     *
     * @example
     * // 基础初始化
     * kiko.ui.pager.init({debug: true});
     *
     * // 带行为初始化
     * kiko.ui.pager.init({debug: true}, {
     *   'hello': {
     *     type: 'function',
     *     handler: function() { return '你好'; },
     *     target: '#output'
     *   }
     * });
     */
    init: function (options, actions) {
      // 更新配置
      if (options && typeof options === 'object') {
        this.config = $.extend(this.config, options);
      }

      this.log('初始化PageAction', { config: this.config, actions });

      // 初始化行为配置
      if (actions) {
        this.addActions(actions);
      }

      // 绑定默认选择器
      this.bindDefaultSelectors();

      // 绑定锚点链接拦截
      if (this.config.enableAnchorCapture) {
        this.bindAnchorCapture();
      }

      return this;
    },

    /**
     * 添加多个行为配置
     *
     * 支持数组或对象两种形式的行为配置。
     *
     * @param {Array|Object} actions - 行为配置数组或对象
     * @returns {Object} PageAction实例，支持链式调用
     *
     * @example
     * // 数组形式
     * pager.addActions([
     *   {id: 'action1', type: 'function', handler: function() {...}},
     *   {id: 'action2', type: 'url', url: '/api/data'}
     * ]);
     *
     * // 对象形式
     * pager.addActions({
     *   'action1': {type: 'function', handler: function() {...}},
     *   'action2': {type: 'url', url: '/api/data'}
     * });
     */
    addActions: function (actions) {
      if (Array.isArray(actions)) {
        // 处理数组形式的配置
        actions.forEach((action) => {
          if (action.id) {
            // 确定行为类型
            this.determineActionType(action);
            this.actions[action.id] = action;
          } else {
            this.log('行为配置缺少id字段', action, 'warn');
          }
        });
      } else if (actions && typeof actions === 'object') {
        // 处理对象形式的配置
        for (const id in actions) {
          const action = actions[id];
          action.id = id; // 确保action知道自己的ID
          // 确定行为类型
          this.determineActionType(action);
          this.actions[id] = action;
        }
      }

      // 绑定自定义选择器
      this.bindCustomSelectors();

      return this;
    },

    /**
     * 确定行为类型
     * @param {Object} action - 行为配置对象
     * @private
     */
    determineActionType: function (action) {
      // 如果没有显式指定type，根据handler或url自动确定
      if (!action.type) {
        if (typeof action.handler === 'function') {
          action.type = 'function';
        } else if (
          typeof action.url === 'string' ||
          typeof action.url === 'function'
        ) {
          action.type = 'url';
        } else {
          this.log(`无法确定行为(${action.id})的类型`, action, 'warn');
        }
      }
    },

    /**
     * 添加单个行为配置
     *
     * 行为配置支持以下参数：
     * 1. 通用参数：
     *   - id {String} - 行为ID(通过方法参数传入)
     *   - type {String} - 行为类型，可为'function'或'url'
     *   - selector {String} - 绑定元素的选择器(可选)
     *   - event {String} - 触发事件类型，默认为'click'，支持多个事件用空格分隔(可选)
     *   - target {String} - 目标元素ID或选择器(可选)
     *   - data {Object} - 行为的附加数据，会与通过HTML属性收集的数据合并(可选)
     *   - before {Function} - 执行前回调，返回false可阻止执行(可选)
     *   - after {Function} - 执行后回调，无论成功失败都会执行(可选)
     *
     * 2. 函数类型行为参数(type = 'function')：
     *   - handler {Function} - 处理函数，接收(actionId, target, eventData, data)参数
     *
     * 3. URL类型行为参数(type = 'url')：
     *   - url {String|Function} - 请求URL或返回URL的函数
     *   - cache {Boolean} - 是否缓存响应，默认与全局配置相同(可选)
     *   - isShowHtml {Boolean} - 是否以HTML方式显示响应内容，默认为false(可选)
     *   - success {Function} - 请求成功回调(可选)
     *   - error {Function} - 请求失败回调(可选)
     *
     * @param {String} id - 行为ID
     * @param {Object} actionConfig - 行为配置对象
     * @returns {Object} PageAction实例，支持链式调用
     *
     * @example
     * // 函数类型行为
     * pager.addAction('show-message', {
     *   type: 'function',
     *   handler: function(id, target, event, data) {
     *     return '你好，' + data.name;
     *   },
     *   target: '#output',
     *   data: { defaultName: '访客' }
     * });
     *
     * // URL类型行为
     * pager.addAction('load-content', {
     *   type: 'url',
     *   url: '/api/content',
     *   target: '.content-area',
     *   cache: true,
     *   data: { section: 'home' },
     *   isShowHtml: true
     * });
     */
    addAction: function (id, actionConfig) {
      if (!id || typeof id !== 'string') {
        this.log('添加行为需提供有效的ID', null, 'error');
        return this;
      }

      actionConfig.id = id;

      // 确定行为类型
      this.determineActionType(actionConfig);

      this.actions[id] = actionConfig;
      this.log('添加行为', { id, config: actionConfig });

      // 如果配置了选择器，绑定事件
      if (actionConfig.selector) {
        this.bindSelector(
          id,
          actionConfig.selector,
          actionConfig.event || this.config.defaultEvent,
        );
      }

      return this;
    },

    /**
     * 移除行为配置
     * @param {String} id - 行为ID
     * @returns {Object} PageAction实例，支持链式调用
     *
     * @example
     * pager.removeAction('load-content');
     */
    removeAction: function (id) {
      const action = this.actions[id];
      if (action) {
        // 解除选择器绑定
        if (action.selector) {
          const event = action.event || this.config.defaultEvent;
          $(document).off(`${event}.pageAction.${id}`, action.selector);
        }

        delete this.actions[id];
        this.log('移除行为', { id });
      }

      return this;
    },

    /**
     * 手动触发行为
     * @param {String} id - 行为ID
     * @param {Object} data - 额外数据，会与行为配置中的data合并
     * @param {Element|jQuery} element - 触发元素（可选）
     * @returns {Object} PageAction实例，支持链式调用
     *
     * @example
     * pager.trigger('show-message', {name: '小明'});
     */
    trigger: function (id, data, element) {
      this.log('手动触发行为', { id, data });

      if (!this.actions[id]) {
        this.log(`未找到ID为${id}的行为配置`, null, 'error');
        return this;
      }

      const actionData = {
        action: id,
        data: data || {},
        element: element || document.body,
      };

      this.executeAction(id, actionData);
      return this;
    },

    /**
     * 绑定默认选择器事件
     * @private
     */
    bindDefaultSelectors: function () {
      const self = this;

      // 解绑之前的事件（如果有）
      $(document).off('click.pageAction.default');

      // 绑定默认选择器的点击事件
      $(document).on(
        'click.pageAction.default',
        this.config.defaultSelector,
        function (e) {
          e.preventDefault();

          const $this = $(this);
          const actionId = $this.attr('data-action');

          if (!actionId) return;

          const actionData = {
            action: actionId,
            data: self.collectDataAttributes($this),
            element: this,
          };

          self.executeAction(actionId, actionData);
        },
      );

      this.log('已绑定默认选择器', { selector: this.config.defaultSelector });
    },

    /**
     * 绑定自定义选择器事件
     * @private
     */
    bindCustomSelectors: function () {
      for (const id in this.actions) {
        const action = this.actions[id];
        if (
          action.selector &&
          action.selector !== this.config.defaultSelector
        ) {
          this.bindSelector(
            id,
            action.selector,
            action.event || this.config.defaultEvent,
          );
        }
      }
    },

    /**
     * 绑定锚点链接拦截
     * @private
     */
    bindAnchorCapture: function () {
      const self = this;

      // 解绑之前的事件（如果有）
      $(document).off('click.pageAction.anchor');

      // 绑定所有带锚点的链接
      $(document).on('click.pageAction.anchor', 'a[href^="#"]', function (e) {
        const $this = $(this);
        const href = $this.attr('href');

        // 忽略空锚点和页面内部导航
        if (href === '#' || href === '#top') return;

        const actionId = href.substring(1); // 移除#前缀

        // 检查是否有对应的行为配置
        if (self.actions[actionId]) {
          e.preventDefault();

          const actionData = {
            action: actionId,
            data: self.collectDataAttributes($this),
            element: this,
          };

          self.executeAction(actionId, actionData);
        }
      });

      this.log('已绑定锚点链接拦截');
    },

    /**
     * 绑定特定选择器的事件
     * @param {String} id - 行为ID
     * @param {String} selector - 选择器
     * @param {String} eventType - 事件类型
     * @private
     */
    bindSelector: function (id, selector, eventType) {
      const self = this;
      const events = eventType.split(' '); // 支持多个事件

      for (let i = 0; i < events.length; i++) {
        const event = events[i];

        // 解绑之前的事件（如果有）
        $(document).off(`${event}.pageAction.${id}`, selector);

        // 绑定新事件
        $(document).on(`${event}.pageAction.${id}`, selector, function (e) {
          e.preventDefault();

          const $this = $(this);
          const actionData = {
            action: id,
            data: self.collectDataAttributes($this),
            element: this,
          };

          self.executeAction(id, actionData);
        });
      }

      this.log('已绑定选择器事件', { id, selector, eventType });
    },

    /**
     * 执行行为
     * @param {String} actionId - 行为ID
     * @param {Object} eventData - 事件数据
     * @private
     */
    executeAction: function (actionId, eventData) {
      const action = this.actions[actionId];

      if (!action) {
        this.log(`未找到ID为${actionId}的行为配置`, null, 'error');
        return;
      }

      this.log('执行行为', { actionId, eventData });

      // 合并配置数据和事件数据
      if (action.data) {
        eventData.data = $.extend({}, action.data, eventData.data);
      }

      // 调用全局初始化函数
      if (typeof this.config.init === 'function') {
        const continueExecution = this.config.init(action, eventData);
        if (continueExecution === false) {
          this.log('行为执行被全局init回调中断', { actionId });

          // 执行全局完成回调，表示未成功执行
          if (typeof this.config.complete === 'function') {
            this.config.complete(false, action, eventData);
          }

          return;
        }
      }

      // 执行before回调
      if (typeof action.before === 'function') {
        const continueExecution = action.before(actionId, eventData);
        if (continueExecution === false) {
          this.log('行为执行被before回调中断', { actionId });

          // 执行全局完成回调，表示未成功执行
          if (typeof this.config.complete === 'function') {
            this.config.complete(false, action, eventData);
          }

          return;
        }
      }

      try {
        // 根据行为类型执行相应处理
        if (
          action.type === 'function' ||
          typeof action.handler === 'function'
        ) {
          // 处理函数类型的行为
          this.handleFunctionAction(action, actionId, eventData);
        } else if (
          action.type === 'url' ||
          typeof action.url === 'string' ||
          typeof action.url === 'function'
        ) {
          // 处理URL类型的行为
          this.handleUrlAction(action, actionId, eventData);
        } else {
          throw new Error(`行为${actionId}未定义处理函数或URL`);
        }
      } catch (error) {
        this.log(`执行行为${actionId}时发生错误`, error, 'error');

        // 执行error回调
        if (typeof action.error === 'function') {
          action.error(error, actionId, eventData);
        } else if (typeof this.config.errorHandler === 'function') {
          // 如果没有自定义错误处理，使用全局错误处理器
          this.config.errorHandler(error, 'execution_error', {
            action: action,
            actionId: actionId,
            eventData: eventData,
          });
        }

        // 函数类型行为在出错时需要调用全局complete
        if (
          action.type === 'function' ||
          typeof action.handler === 'function'
        ) {
          if (typeof this.config.complete === 'function') {
            this.config.complete(false, action, eventData);
          }
        }
      }
    },

    /**
     * 处理函数类型的行为
     * @param {Object} action - 行为配置
     * @param {String} actionId - 行为ID
     * @param {Object} eventData - 事件数据
     * @private
     */
    handleFunctionAction: function (action, actionId, eventData) {
      // 获取目标元素（从配置或元素属性）
      const target = this.getTargetFromAction(action, eventData);

      try {
        // 执行处理函数
        const result = action.handler(
          actionId,
          target,
          eventData,
          eventData.data,
        );

        // 如果返回了内容且有目标元素，则更新目标元素
        if (result !== undefined && target) {
          this.updateTarget(target, result, action.isShowHtml === true);
        }

        // 执行after回调
        if (typeof action.after === 'function') {
          action.after(actionId, eventData, result);
        }

        // 执行全局完成回调
        if (typeof this.config.complete === 'function') {
          this.config.complete(true, action, eventData);
        }
      } catch (error) {
        this.log(`执行函数行为${actionId}的handler时发生错误`, error, 'error');

        // 处理错误
        if (typeof action.error === 'function') {
          action.error(error, actionId, eventData);
        } else if (typeof this.config.errorHandler === 'function') {
          this.config.errorHandler(error, 'handler_error', {
            action: action,
            actionId: actionId,
            eventData: eventData,
          });
        }

        // 执行after回调（即使出错也执行）
        if (typeof action.after === 'function') {
          action.after(actionId, eventData, null);
        }

        // 执行全局完成回调，标识执行失败
        if (typeof this.config.complete === 'function') {
          this.config.complete(false, action, eventData);
        }

        // 重新抛出错误以便外层捕获
        throw error;
      }
    },

    /**
     * 处理URL类型的行为
     * @param {Object} action - 行为配置
     * @param {String} actionId - 行为ID
     * @param {Object} eventData - 事件数据
     * @private
     */
    handleUrlAction: function (action, actionId, eventData) {
      // 解析URL（如果是函数）
      const url =
        typeof action.url === 'function'
          ? action.url(actionId, eventData)
          : action.url;

      if (!url) {
        throw new Error(`行为${actionId}的URL为空`);
      }

      // 获取目标元素
      const target = this.getTargetFromAction(action, eventData);
      if (!target) {
        this.log(`行为${actionId}未指定target目标`, null, 'warn');
        return;
      }

      // 检查缓存
      const useCache =
        action.cache !== undefined ? action.cache : this.config.cache;
      if (useCache && this.cache[url]) {
        this.log('使用缓存的URL响应', { url });
        this.updateTarget(target, this.cache[url], action.isShowHtml === true);

        // 执行after回调
        if (typeof action.after === 'function') {
          action.after(actionId, eventData, this.cache[url]);
        }

        // 执行全局完成回调
        if (typeof this.config.complete === 'function') {
          this.config.complete(true, action, eventData);
        }

        return;
      }

      // 显示加载提示
      const $target = $(target);
      if ($target.length) {
        // 保存原始内容用于恢复
        const originalContent = $target.html();
        $target.html(action.loadingText || this.config.loadingText);
      }

      // 准备请求参数 - 使用合并后的数据
      const requestData = eventData.data || {};

      // 执行AJAX请求
      const self = this;
      $.get(url, requestData)
        .done(function (response) {
          self.log('URL请求成功', { url, response });

          // 更新缓存
          if (useCache) {
            self.cache[url] = response;
          }

          // 更新目标元素
          if ($target.length) {
            self.updateTarget(target, response, action.isShowHtml === true);
          }

          // 执行success回调
          if (typeof action.success === 'function') {
            action.success(response, actionId, eventData);
          }

          // 执行after回调
          if (typeof action.after === 'function') {
            action.after(actionId, eventData, response);
          }

          // 执行全局完成回调
          if (typeof self.config.complete === 'function') {
            self.config.complete(true, action, eventData);
          }
        })
        .fail(function (xhr, status, error) {
          self.log('URL请求失败', { url, status, error }, 'error');

          // 显示错误信息
          if ($target.length) {
            $target.html(`<div>加载失败: ${error}</div>`);
          }

          // 执行error回调
          if (typeof action.error === 'function') {
            action.error(xhr, status, error, actionId, eventData);
          } else if (typeof self.config.errorHandler === 'function') {
            // 如果没有自定义错误处理，使用全局错误处理器
            self.config.errorHandler(error, 'ajax_error', {
              xhr: xhr,
              status: status,
              url: url,
              action: action,
              actionId: actionId,
            });
          }

          // 执行after回调（即使出错也执行）
          if (typeof action.after === 'function') {
            action.after(actionId, eventData, null);
          }

          // 执行全局完成回调
          if (typeof self.config.complete === 'function') {
            self.config.complete(false, action, eventData);
          }
        });
    },

    /**
     * 从行为配置或元素属性中获取目标
     * @param {Object} action - 行为配置
     * @param {Object} eventData - 事件数据
     * @returns {String} 目标选择器或元素ID
     * @private
     */
    getTargetFromAction: function (action, eventData) {
      // 优先使用配置中的target
      if (action.target) {
        return action.target;
      }

      // 其次使用元素的target属性
      if (eventData.element) {
        const targetAttr = $(eventData.element).attr(
          this.config.targetAttribute,
        );
        if (targetAttr) {
          return targetAttr;
        }
      }

      return null;
    },

    /**
     * 更新目标元素内容
     * @param {String} target - 目标元素ID或选择器
     * @param {String} content - 内容
     * @param {Boolean} isHtml - 是否按HTML解析，false则作为文本
     * @private
     */
    updateTarget: function (target, content, isHtml) {
      // 如果target以#开头且不包含空格，视为ID选择器
      const $target =
        target.charAt(0) === '#' && target.indexOf(' ') === -1
          ? $(target)
          : $(target.charAt(0) === '#' ? target : '#' + target);

      if (!$target.length) {
        this.log(`未找到目标元素: ${target}`, null, 'warn');
        return;
      }

      // 根据模式更新内容
      if (isHtml) {
        $target.html(content);
      } else {
        $target.text(content);
      }

      this.log('已更新目标元素', { target, isHtml });
    },

    /**
     * 收集元素上的data属性
     * @param {jQuery} $element - jQuery元素对象
     * @returns {Object} 收集到的data属性对象
     * @private
     */
    collectDataAttributes: function ($element) {
      const data = {};
      const prefix = this.config.dataAttributePrefix;
      const prefixLength = prefix.length;

      // 遍历元素的所有属性
      $.each($element[0].attributes, function (i, attr) {
        if (attr.name.indexOf(prefix) === 0) {
          // 将属性名转换为驼峰命名
          const key = attr.name
            .substring(prefixLength)
            .replace(/-([a-z])/g, function (match, letter) {
              return letter.toUpperCase();
            });

          // 排除特定属性（如action和target）
          if (key !== 'action' && key !== 'target') {
            data[key] = attr.value;
          }
        }
      });

      return data;
    },

    /**
     * 清除缓存
     * @param {String} url - 可选的URL，不指定则清空所有缓存
     * @returns {Object} PageAction实例，支持链式调用
     *
     * @example
     * // 清除特定URL缓存
     * pager.clearCache('/api/content');
     *
     * // 清除所有缓存
     * pager.clearCache();
     */
    clearCache: function (url) {
      if (url) {
        delete this.cache[url];
        this.log('已清除URL缓存', { url });
      } else {
        this.cache = {};
        this.log('已清除所有缓存');
      }

      return this;
    },

    /**
     * 输出日志
     * @param {String} message - 日志消息
     * @param {*} data - 相关数据
     * @param {String} level - 日志级别
     * @private
     */
    log: function (message, data, level = 'info') {
      if (!this.config.debug) return;

      const prefix = '[PageAction]';

      switch (level) {
        case 'error':
          console.error(prefix, message, data || '');
          break;
        case 'warn':
          console.warn(prefix, message, data || '');
          break;
        case 'info':
        default:
          console.log(prefix, message, data || '');
          break;
      }
    },
  };

  // 导出到kiko命名空间
  kiko.ui.pager = PageAction;
})(jQuery, window.kiko || (window.kiko = {}));


// ---- ui/valid.js ----
(function ($, kiko) {
  // 私有函数：计算字符串长度
  const strLen = (str) => str.length;

  // 私有函数：按字符数截取字符串
  const substrByChar = (str, charLength) => str.substring(0, charLength);

  // 回调函数注册对象
  const callbackRegistry = {};

  // 回调函数事件类型注册对象
  const callbackEvents = {};

  // 注意：多语言定义已移至 kiko/src/i18n/ 目录下的语言文件中

  $.fn.valid = function () {
    const validators = {
      validname: {
        regex: /^[a-zA-Z0-9_-]+$/,
        key: 'validname',
      },
      en: {
        regex: /^[a-zA-Z]+$/,
        key: 'en',
      },
      domain: {
        regex: /^((?!-)[A-Za-z0-9-]{1,63}(?<!-)\.)+[A-Za-z]{2,6}$/,
        key: 'domain',
      },
      mobile: {
        regex: /^\+?[\d\s-]{7,}$/,
        key: 'mobile',
      },
      int: {
        regex: /^-?\d+$/,
        key: 'int',
      },
      email: {
        regex:
          /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*$/,
        key: 'email',
      },
      date: {
        regex: /^(\d{4}-\d{2}-\d{2}|\d{2}\/\d{2}\/\d{4}|\d{2}\.\d{2}\.\d{4})$/,
        key: 'date',
      },
      url: {
        regex:
          /^(https?:\/\/)?([\da-z\.-]+)\.([a-z\.]{2,6})([\/\w \.-]*)*\/?$/i,
        key: 'url',
      },
      pwd: {
        regex: /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/,
        key: 'pwd',
      },
      strongpwd: {
        regex: /^(?=.*[A-Za-z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!%*#?&]{8,}$/,
        key: 'strongpwd',
      },
    };

    const methods = {
      /**
       * 初始化验证
       */
      init() {
        // 标记表单已初始化，避免重复初始化
        if (this.is('form')) {
          this.attr('data-loadedvalid', 'true');
        }

        this.find('[valid]').each((_, obj) => {
          const $obj = $(obj);
          if ($obj.data('loadedvalid')) return;

          // 查找已存在的错误反馈容器，如果没有则创建一个
          if (!$obj.next('div.invalid-feedback').length) {
            $obj.after('<div class="invalid-feedback"></div>');
          }

          $obj.data('loadedvalid', true);

          // 分析验证规则，决定绑定哪些事件
          const validRules = JSON.parse($obj.attr('valid'));
          const hasCallbackValidation = validRules.some(
            (rule) => (rule.type || rule) === 'callback',
          );

          // 根据验证类型绑定不同的事件
          if (hasCallbackValidation) {
            // 对于常规验证，绑定input和blur事件
            $obj.on('input blur', (e) => {
              // 不再全局跳过回调，而是在checkElement中根据事件类型判断
              methods.checkElement($obj, {
                event: e.type,
              });
            });

            // 对回调验证规则进行单独处理
            validRules.forEach((rule) => {
              if ((rule.type || rule) === 'callback') {
                const callbackName = rule.fn;
                if (callbackName && callbackRegistry[callbackName]) {
                  // 使用自定义事件或默认为blur
                  const eventType = callbackEvents[callbackName] || 'blur';

                  // 如果事件不是input或blur，需要额外绑定
                  if (eventType !== 'input' && eventType !== 'blur') {
                    $obj.on(eventType, () => {
                      methods.checkElement($obj, {
                        event: eventType,
                        onlyCallback: true,
                        callbackName: callbackName,
                      });
                    });
                  }
                }
              }
            });
          } else {
            // 没有回调验证，只绑定input和blur事件
            $obj.on('input blur', (e) =>
              methods.checkElement($obj, { event: e.type }),
            );
          }
          validRules.forEach((json) => {
            if (json.show === true) {
              // 查找已存在的字符计数容器，如果没有则创建一个,文字靠右
              if (!$obj.next('span').length) {
                $obj.after('<span />');
              }
              $obj
                .next('span')
                .addClass('block w-full text-xs text-gray-500 text-right mt-2');
              $obj.on('input', methods.updateCharCount);
              methods.updateCharCount.call($obj[0]);
            }
          });
        });

        return this;
      },

      /**
       * 更新字符计数
       */
      updateCharCount() {
        const $obj = $(this);
        const value = $obj.val();
        const validRules = JSON.parse($obj.attr('valid'));

        for (const json of validRules) {
          if (json.show === true) {
            const maxlen = json.max;
            if (strLen(value) > maxlen) {
              $obj.val(substrByChar(value, maxlen));
            }
            const remainingChars = maxlen - strLen($obj.val());
            $obj.nextAll('span:first').html(
              kiko.i18n.getMessage('charCount', {
                count: remainingChars,
              }),
            );
            break;
          }
        }
      },

      /**
       * 检查所有元素的错误
       * @returns {boolean} 是否有错误
       */
      checkError() {
        const $elements = $(this).find('[valid]');
        const errorsWithElements = $elements
          .map((_, obj) => {
            const $obj = $(obj);
            const hasError = methods.checkElement($obj, { event: 'submit' });
            return { $element: $obj, hasError };
          })
          .get();

        const hasErrors = errorsWithElements.some((item) => item.hasError);

        // 如果有错误，自动将焦点定位到第一个出错的元素
        if (hasErrors) {
          const firstErrorElement = errorsWithElements.find(
            (item) => item.hasError,
          ).$element;
          firstErrorElement.focus();
        }

        return hasErrors;
      },

      /**
       * 检查单个元素的验证
       * @param {jQuery} $obj - 要检查的jQuery对象
       * @param {Object} options - 验证选项
       * @param {string} options.event - 触发验证的事件类型
       * @param {boolean} options.skipCallback - 是否跳过回调验证
       * @param {boolean} options.onlyCallback - 是否只执行回调验证
       * @param {string} options.callbackName - 指定执行的回调名称
       * @returns {boolean} 是否有错误
       */
      checkElement($obj, options = {}) {
        const validRules = JSON.parse($obj.attr('valid'));
        const $labelError = $obj.nextAll('div.invalid-feedback:first');
        let hasError = false;
        let errorMsg = '';

        const eventType = options.event || 'blur'; // 默认事件类型为 blur

        for (const json of validRules) {
          const type = json.type || json;
          const val = $obj.val();

          // 如果设置了只执行指定回调，且当前规则不是指定的回调，则跳过
          if (
            options.onlyCallback &&
            type === 'callback' &&
            json.fn !== options.callbackName
          ) {
            continue;
          }

          // 如果设置了只执行回调，且当前规则不是回调类型，则跳过
          if (options.onlyCallback && type !== 'callback') {
            continue;
          }

          // 移除全局跳过回调的检查，改为仅根据事件类型判断
          // if (options.skipCallback && type === 'callback') {
          //   continue;
          // }

          // 如果是回调类型，检查事件类型是否匹配
          if (type === 'callback') {
            const callbackName = json.fn;
            // 如果指定了回调名称且与当前规则不匹配，则跳过
            if (options.callbackName && options.callbackName !== callbackName) {
              continue;
            }

            // 获取回调函数注册的事件类型
            const callbackEventType = callbackEvents[callbackName] || 'blur';

            // 如果当前事件类型与回调注册的事件类型不匹配，则跳过
            // submit 事件是特例，会触发所有验证
            if (eventType !== callbackEventType && eventType !== 'submit') {
              continue;
            }
          }

          switch (type) {
            case 'emptyquit':
              if (strLen(val) === 0) return false;
              break;
            case 'required':
              if (strLen(val) === 0)
                errorMsg = json.msg || kiko.i18n.getMessage('required');
              break;
            case 'limit':
              const len = strLen(val);
              if (json.min !== undefined && len < json.min) {
                errorMsg =
                  json.msg ||
                  kiko.i18n.getMessage('limitMin', { min: json.min });
              }
              if (json.max !== undefined && len > json.max) {
                errorMsg =
                  json.msg ||
                  kiko.i18n.getMessage('limitMax', { max: json.max });
              }
              break;
            case 'validname':
            case 'en':
            case 'domain':
            case 'mobile':
            case 'int':
            case 'email':
            case 'date':
            case 'url':
              if (
                validators[type] &&
                !validators[type].regex.test(val) &&
                val !== ''
              ) {
                errorMsg =
                  json.msg || kiko.i18n.getMessage(validators[type].key);
              }
              break;
            case 'regexp':
              const reg = new RegExp(`^${json.expression}$`, 'iu');
              if (!reg.test(val))
                errorMsg = json.msg || kiko.i18n.getMessage('regexp');
              break;
            case 'range':
              if (/^\d+$/.test(val)) {
                const numVal = parseInt(val, 10);
                if (numVal < json.min || numVal > json.max) {
                  errorMsg =
                    json.msg ||
                    kiko.i18n.getMessage('range', {
                      min: json.min,
                      max: json.max,
                    });
                }
              } else {
                errorMsg = kiko.i18n.getMessage('rangeInt');
              }
              break;
            case 'compareto':
              if ($(`#${json.destid}`).val() !== val || val === '') {
                errorMsg = json.msg || kiko.i18n.getMessage('compareto');
              }
              break;
            case 'tag':
              if (val.split(json.mark || ' ').length > json.max && val !== '') {
                errorMsg =
                  json.msg || kiko.i18n.getMessage('tag', { max: json.max });
              }
              break;
            case 'callback':
              if (typeof callbackRegistry[json.fn] === 'function') {
                const result = callbackRegistry[json.fn]($obj.attr('id'), val);
                // 支持异步验证（返回Promise）
                if (result instanceof Promise) {
                  // 临时标记为验证中
                  $obj.addClass('validating');
                  result.then((validationResult) => {
                    $obj.removeClass('validating');

                    // 处理不同类型的返回值
                    let isValid = true;
                    let customErrorMsg = '';

                    if (validationResult === false) {
                      // 布尔值 false
                      isValid = false;
                      customErrorMsg =
                        json.msg || kiko.i18n.getMessage('callback');
                    } else if (
                      typeof validationResult === 'string' &&
                      validationResult !== ''
                    ) {
                      // 非空字符串表示自定义错误消息
                      isValid = false;
                      customErrorMsg = validationResult;
                    } else if (
                      validationResult &&
                      typeof validationResult === 'object'
                    ) {
                      // 对象格式 {valid: boolean, message: string}
                      isValid = validationResult.valid !== false;
                      if (!isValid && validationResult.message) {
                        customErrorMsg = validationResult.message;
                      } else if (!isValid) {
                        customErrorMsg =
                          json.msg || kiko.i18n.getMessage('callback');
                      }
                    }

                    if (!isValid) {
                      $labelError
                        .text(customErrorMsg)
                        .attr('class', 'invalid-feedback');
                      $obj
                        .removeClass('is-invalid is-valid')
                        .addClass('is-invalid');
                    } else if (!$obj.hasClass('is-invalid')) {
                      $obj
                        .removeClass('is-invalid is-valid')
                        .addClass('is-valid');
                    }
                  });
                  // 异步验证不阻塞当前验证流程
                  continue;
                } else {
                  // 处理同步验证结果
                  // 支持多种返回格式
                  if (result === false) {
                    // 布尔值 false，使用默认错误消息
                    errorMsg = json.msg || kiko.i18n.getMessage('callback');
                  } else if (typeof result === 'string' && result !== '') {
                    // 非空字符串表示自定义错误消息
                    errorMsg = result;
                  } else if (result && typeof result === 'object') {
                    // 对象格式 {valid: boolean, message: string}
                    if (result.valid === false) {
                      errorMsg =
                        result.message ||
                        json.msg ||
                        kiko.i18n.getMessage('callback');
                    }
                  }
                }
              } else {
                console.error(`Callback function ${json.fn} is not registered`);
              }
              break;
          }

          if (errorMsg) {
            $labelError.text(errorMsg).attr('class', 'invalid-feedback');
            $obj.removeClass('is-invalid is-valid').addClass('is-invalid');
            hasError = true;
            break;
          }
        }

        if (!hasError && !$obj.hasClass('validating')) {
          $labelError.text('');
          $obj.removeClass('is-invalid is-valid').addClass('is-valid');
        }
        return hasError;
      },
    };

    if (typeof arguments[0] === 'string' && methods[arguments[0]]) {
      return methods[arguments[0]].apply(
        this,
        Array.prototype.slice.call(arguments, 1),
      );
    } else if (typeof arguments[0] === 'object' || !arguments[0]) {
      return methods.init.apply(this, arguments);
    } else {
      $.error('Method ' + arguments[0] + ' does not exist on jQuery.valid');
    }
  };

  /**
   * 注册自定义回调函数
   * @param {string} name - 回调函数的名称
   * @param {function} callback - 回调函数，支持以下返回值:
   *   - true: 验证通过
   *   - false: 验证失败，使用默认错误消息
   *   - string: 验证失败，使用返回的字符串作为自定义错误消息
   *   - {valid: boolean, message: string}: 对象形式，valid表示验证结果，message为自定义错误消息
   *   - Promise: 异步验证，Promise解析后的值支持以上所有格式
   * @param {string} [eventType='blur'] - 触发事件类型，默认为blur
   */
  $.fn.valid.registerCallback = function (name, callback, eventType = 'blur') {
    if (typeof callback === 'function') {
      callbackRegistry[name] = callback;
      callbackEvents[name] = eventType;
    } else {
      console.error(`Invalid callback function for ${name}`);
    }
  };

  // 在Kiko命名空间中注册valid组件
  kiko.ui.valid = {
    /**
     * 初始化验证组件
     */
    init: function () {
      kiko.core.log('正在初始化表单验证组件...');

      // 初始化页面中的表单验证
      $('form').valid();

      // 也初始化不在表单内的验证字段
      $('[valid]').not('form [valid]').valid();

      kiko.core.log('表单验证初始化完成');
    },

    /**
     * 注册回调函数
     * @param {string} name - 回调函数名称
     * @param {function} callback - 回调函数
     * @param {string} [eventType='blur'] - 触发事件类型，默认为blur
     */
    registerCallback: function (name, callback, eventType = 'blur') {
      $.fn.valid.registerCallback(name, callback, eventType);
    },

    /**
     * 刷新表单验证
     * 手动初始化指定表单或所有表单的验证
     * @param {string|jQuery} [selector] - 表单选择器或jQuery对象，不提供则刷新所有表单
     */
    refresh: function (selector) {
      if (selector) {
        $(selector).valid();
      } else {
        $('form').valid();
        $('[valid]').not('form [valid]').valid();
      }

      kiko.core.log('表单验证已刷新');
      return this;
    },
  };

  // 提供jQuery插件方法
  $.fn.kikoValid = function (options) {
    return this.valid(options);
  };
})(jQuery, kiko);


// ---- ui/tooltip.js ----
(function ($, kiko) {
  'use strict';

  /**
   * 默认配置选项
   * @type {Object}
   */
  const defaults = {
    position: 'bottom', // 提示框显示位置
    waitTime: 2000, // 显示内容延迟时间
    hideWaitTime: 250, // 隐藏提示框延迟时间
    loading: '加载中...', // 加载内容前显示文字
    event: 'mouseover', // 触发事件
    theme: 'bg-gray-800 text-white px-3 py-2 rounded-lg shadow-lg text-sm', // 默认主题
    autoClose: true, // 是否自动关闭
    alwaysLoad: false, // 是否总是重新加载内容
    zIndex: 1000, // z-index层级
  };

  /**
   * 全局状态管理
   */
  let hideEvent = 0; // 隐藏内容延迟事件
  let clickTooltipTriggers = new Set(); // 存储通过click事件触发的tooltip元素
  let globalClickHandlerBound = false; // 标记是否已绑定全局点击事件

  /**
   * 全局点击事件处理器
   * 当点击页面其他区域时，隐藏所有通过click事件显示的tooltip
   */
  const globalClickHandler = function (e) {
    let shouldHide = true;

    // 检查点击的目标是否是tooltip触发器或tooltip容器
    clickTooltipTriggers.forEach(function (triggerSelector) {
      const $trigger = $(triggerSelector);
      const targetId = $trigger.data('tooltip-target');

      // 如果点击的是触发器本身，不隐藏
      if ($trigger.is(e.target) || $trigger.has(e.target).length > 0) {
        shouldHide = false;
        return false;
      }

      // 如果点击的是tooltip容器，不隐藏
      if (targetId) {
        const $container = $('#' + targetId);
        if ($container.is(e.target) || $container.has(e.target).length > 0) {
          shouldHide = false;
          return false;
        }
      } else {
        // 检查动态tooltip容器
        if ($(e.target).closest('.kiko-tooltip-dynamic').length > 0) {
          shouldHide = false;
          return false;
        }
      }
    });

    // 如果应该隐藏，则隐藏所有click触发的tooltip
    if (shouldHide) {
      hideClickTooltips();
    }
  };

  /**
   * 隐藏所有通过click事件触发的tooltip
   */
  const hideClickTooltips = function () {
    clickTooltipTriggers.forEach(function (triggerSelector) {
      const $trigger = $(triggerSelector);
      const targetId = $trigger.data('tooltip-target');

      if (targetId) {
        // target模式：隐藏目标元素
        $('#' + targetId).hide();
      } else {
        // 标准模式：移除动态tooltip
        $('.kiko-tooltip-dynamic').remove();
      }
    });
  };

  /**
   * 绑定全局点击事件监听器
   */
  const bindGlobalClickHandler = function () {
    if (!globalClickHandlerBound) {
      $(document).on('click.kiko.tooltip.global', globalClickHandler);
      globalClickHandlerBound = true;
    }
  };

  /**
   * 初始化指定元素的tooltip功能
   * 根据元素的data属性配置tooltip行为
   *
   * @param {jQuery} $element - 要初始化的jQuery元素对象
   * @param {Object} customOptions - 自定义配置选项
   */
  const initTooltip = function ($element, customOptions = {}) {
    // 如果已经初始化过，则跳过
    if ($element.attr('kiko-tooltip-loaded') !== undefined) {
      return;
    }

    // 合并配置选项
    const options = $.extend({}, defaults, customOptions);

    // 从data属性读取配置
    const eventConfig = $element.data('tooltip-event') || options.event;
    const autoClose = $element.data('tooltip-auto-close') !== 'false';

    // 处理多事件支持
    let events = [];
    if (typeof eventConfig === 'string') {
      // 支持逗号分隔的多个事件
      events = eventConfig.split(',').map((e) => e.trim());
    } else {
      events = [eventConfig];
    }

    // 检查是否使用target模式 - 这是主要的差异点
    const targetId = $element.data('tooltip-target');
    const isTargetMode = !!targetId;

    // target模式的差异处理：验证目标元素是否存在
    if (isTargetMode) {
      const $target = $('#' + targetId);
      if ($target.length === 0) {
        kiko.core.log('Tooltip target element not found', targetId, 'warn');
        return;
      }
    }

    // 统一的事件绑定逻辑 - 支持多个事件
    events.forEach((event) => {
      $element.on(event + '.kiko.tooltip', function (e) {
        // 如果是click事件，阻止事件冒泡以防止立即触发全局点击处理器
        if (event === 'click') {
          e.stopPropagation();
        }
        showTooltip($(this), options);
      });
    });

    // 如果包含click事件，添加到click触发器集合并绑定全局点击处理器
    if (events.includes('click')) {
      // 生成唯一的选择器标识
      const elementId =
        $element.attr('id') ||
        'tooltip-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
      if (!$element.attr('id')) {
        $element.attr('id', elementId);
      }
      clickTooltipTriggers.add('#' + elementId);
      bindGlobalClickHandler();
    }

    if (autoClose) {
      // 为鼠标事件添加自动隐藏
      if (events.includes('mouseover') || events.includes('mouseenter')) {
        $element.on('mouseout.kiko.tooltip', doHideTooltip);
      }
    }

    // 标记为已加载
    $element.attr('kiko-tooltip-loaded', 'true');
  };

  /**
   * 显示tooltip
   * 支持两种模式：target模式（显示目标元素）和标准模式（创建动态tooltip）
   * 两种模式都使用相同的定位逻辑
   *
   * @param {jQuery} $trigger - 触发元素
   * @param {Object} options - 配置选项
   */
  const showTooltip = function ($trigger, options = {}) {
    const config = $.extend({}, defaults, options);

    // 检查是否为target模式
    const targetId = $trigger.data('tooltip-target');
    let $container;

    if (targetId) {
      // target模式：使用指定的目标元素作为容器
      $container = $('#' + targetId);
      if ($container.length === 0) {
        kiko.core.log('Tooltip target element not found', targetId, 'warn');
        return;
      }
    } else {
      // 标准模式：创建动态tooltip容器
      const tooltipContent =
        $trigger.data('tooltip') || $trigger.data('tooltip-content');
      if (!tooltipContent) {
        kiko.core.log('No tooltip content found', null, 'warn');
        return;
      }

      // 移除已存在的动态tooltip
      $('.kiko-tooltip-dynamic').remove();

      // 创建动态tooltip容器
      const theme = $trigger.data('tooltip-theme') || config.theme;
      $container = $(
        `<div class="kiko-tooltip-dynamic ${theme}" style="display:none;position:absolute;z-index:${config.zIndex};white-space:nowrap;">${tooltipContent}</div>`,
      );
      $('body').append($container);
    }

    // 统一的定位逻辑 - 适用于两种模式
    // 确保容器已准备好进行定位计算
    $container.css({
      position: 'absolute',
      display: 'block',
      visibility: 'hidden',
      top: '-9999px',
      left: '-9999px',
      zIndex: config.zIndex,
    });

    // 检测触发元素是否使用fixed定位
    const triggerPosition = $trigger.css('position');
    const isFixedTrigger = triggerPosition === 'fixed' || 
                          $trigger.closest('[style*="position: fixed"], [style*="position:fixed"], .fixed').length > 0;
    
    // 获取定位所需的尺寸信息
    let pos;
    if (isFixedTrigger) {
      // 对于fixed元素，使用相对于视口的位置
      const triggerRect = $trigger[0].getBoundingClientRect();
      pos = {
        top: triggerRect.top,
        left: triggerRect.left
      };
      // fixed定位的tooltip需要使用fixed定位
      $container.css('position', 'fixed');
    } else {
      // 普通元素使用offset()获取相对于文档的位置
      pos = $trigger.offset();
      $container.css('position', 'absolute');
    }
    
    const containerWidth = $container.outerWidth();
    const containerHeight = $container.outerHeight();
    const triggerWidth = $trigger.outerWidth();
    const triggerHeight = $trigger.outerHeight();

    let top, left;
    const showPosition = $trigger.data('tooltip-position') || config.position;

    // 获取视口和滚动信息，根据定位类型选择合适的边界参考
    const windowWidth = $(window).width();
    const windowHeight = $(window).height();
    const scrollTop = isFixedTrigger ? 0 : $(window).scrollTop();
    const scrollLeft = isFixedTrigger ? 0 : $(document).scrollLeft();
    const viewportTop = isFixedTrigger ? 0 : scrollTop;
    const viewportBottom = isFixedTrigger ? windowHeight : scrollTop + windowHeight;
    const viewportLeft = isFixedTrigger ? 0 : scrollLeft;
    const viewportRight = isFixedTrigger ? windowWidth : scrollLeft + windowWidth;

    // 使用原有的定位算法，增加边界检测
    switch (showPosition) {
      case 'left':
        left =
          pos.left - containerWidth < viewportLeft
            ? pos.left + triggerWidth + 5
            : pos.left - containerWidth - 5;
        top = pos.top + triggerHeight / 2;
        // 检查垂直边界
        if (top + containerHeight > viewportBottom) {
          top = viewportBottom - containerHeight - 10;
        }
        if (top < viewportTop) {
          top = viewportTop + 10;
        }
        break;
      case 'top':
        left = pos.left;
        top = pos.top - containerHeight - 3;
        // 检查顶部边界，如果tooltip会超出屏幕顶部，改为bottom显示
        if (top < viewportTop) {
          top = pos.top + triggerHeight + 3; // 改为bottom位置
        }
        // 检查右边界，如果tooltip会超出屏幕右边，调整left位置
        if (left + containerWidth > viewportRight) {
          left = viewportRight - containerWidth - 10; // 留10px边距
        }
        // 检查左边界
        if (left < viewportLeft) {
          left = viewportLeft + 10; // 留10px边距
        }
        break;
      case 'right':
        left =
          pos.left + triggerWidth + containerWidth > viewportRight
            ? pos.left - containerWidth - 5
            : pos.left + triggerWidth + 5;
        top = pos.top + triggerHeight / 2;
        // 检查垂直边界
        if (top + containerHeight > viewportBottom) {
          top = viewportBottom - containerHeight - 10;
        }
        if (top < viewportTop) {
          top = viewportTop + 10;
        }
        break;
      case 'bottom':
      default:
        left = pos.left;
        top = pos.top + triggerHeight + 3;
        // 检查底部边界，如果tooltip会超出屏幕底部，改为top显示
        if (top + containerHeight > viewportBottom) {
          top = pos.top - containerHeight - 3; // 改为top位置
        }
        // 检查右边界，如果tooltip会超出屏幕右边，调整left位置
        if (left + containerWidth > viewportRight) {
          left = viewportRight - containerWidth - 10; // 留10px边距
        }
        // 检查左边界
        if (left < viewportLeft) {
          left = viewportLeft + 10; // 留10px边距
        }
        break;
    }

    // 显示tooltip - 重置所有临时样式并正确定位
    $container.css({
      top: top,
      left: left,
      visibility: 'visible',
      display: 'block',
    });

    // 检查是否是通过click事件触发的tooltip
    const eventConfig = $trigger.data('tooltip-event') || config.event;
    let events = [];
    if (typeof eventConfig === 'string') {
      events = eventConfig.split(',').map((e) => e.trim());
    } else {
      events = [eventConfig];
    }
    const isClickTriggered = events.includes('click');

    // 绑定鼠标事件（统一处理逻辑）
    $container
      .on('mouseenter.kiko.tooltip', function () {
        // 鼠标进入时取消隐藏延迟
        if (hideEvent > 0) {
          clearTimeout(hideEvent);
          hideEvent = 0;
        }
      })
      .on('mouseleave.kiko.tooltip', function () {
        // 只有非click触发的tooltip才在鼠标离开时自动隐藏
        if (!isClickTriggered) {
          hideEvent = window.setTimeout(function () {
            if (targetId) {
              // target模式：隐藏目标元素
              $container.hide();
            } else {
              // 标准模式：移除动态tooltip
              $container.remove();
            }
          }, config.hideWaitTime);
        }
      });

    // 为click触发的tooltip添加特殊的点击事件处理
    if (isClickTriggered) {
      $container.on('click.kiko.tooltip', function (e) {
        // 阻止事件冒泡，防止触发全局点击处理器
        e.stopPropagation();
      });
    }

    // target模式需要额外的目标元素事件绑定（只在显示时绑定一次）
    if (targetId) {
      $container
        .off('mouseenter.kiko.tooltip.target mouseleave.kiko.tooltip.target')
        .on('mouseenter.kiko.tooltip.target', function () {
          if (hideEvent > 0) {
            clearTimeout(hideEvent);
            hideEvent = 0;
          }
        })
        .on('mouseleave.kiko.tooltip.target', hideTargetElement);
    }
  };

  /**
   * 延迟隐藏tooltip
   */
  const doHideTooltip = function () {
    const $trigger = $(this);
    const targetId = $trigger.data('tooltip-target');

    hideEvent = window.setTimeout(function () {
      if (targetId) {
        // target模式：隐藏目标元素
        $('#' + targetId).hide();
      } else {
        // 标准模式：移除动态tooltip
        $('.kiko-tooltip-dynamic').remove();
      }
    }, defaults.hideWaitTime);
  };

  /**
   * 隐藏单个target元素
   */
  const hideTargetElement = function () {
    const $target = $(this);
    $target.hide();
  };

  /**
   * 隐藏所有tooltip
   */
  const hideAllTooltips = function () {
    // 隐藏所有动态tooltip
    $('.kiko-tooltip-dynamic').remove();
    // 隐藏所有target模式的tooltip
    $('[data-tooltip-target]').each(function () {
      const targetId = $(this).data('tooltip-target');
      if (targetId) {
        $('#' + targetId).hide();
      }
    });
  };

  /**
   * 公共API方法
   */
  const methods = {
    /**
     * 初始化tooltip组件
     * @param {Object} options - 全局配置选项
     * @returns {Object} tooltip实例，支持链式调用
     */
    init: function (options = {}) {
      // 日志记录
      kiko.core.log('正在初始化tooltip组件...');

      // 合并全局配置到默认配置
      if (options) {
        $.extend(defaults, options);
      }

      // 初始化所有带tooltip相关data属性的元素
      $('[data-tooltip], [data-tooltip-content], [data-tooltip-target]').each(
        function () {
          initTooltip($(this));
        },
      );

      // 日志记录
      kiko.core.log('tooltip组件初始化完成');
      return this;
    },

    /**
     * 显示tooltip
     * @param {string|jQuery} selector - 触发元素选择器或jQuery对象
     * @param {Object} options - 配置选项
     */
    show: function (selector, options = {}) {
      const $trigger = $(selector);
      if ($trigger.length === 0) {
        kiko.core.log('Tooltip trigger element not found', selector, 'warn');
        return;
      }

      // 如果通过options传递了target参数，设置到元素的data属性中
      if (options.target) {
        $trigger.data('tooltip-target', options.target);
      }

      // 如果元素还未初始化，先初始化
      if ($trigger.attr('kiko-tooltip-loaded') === undefined) {
        initTooltip($trigger, options);
      }

      showTooltip($trigger, options);
    },

    /**
     * 隐藏tooltip
     * @param {string|jQuery} selector - 触发元素选择器或jQuery对象
     */
    hide: function (selector) {
      const $trigger = $(selector);
      if ($trigger.length === 0) {
        kiko.core.log('Tooltip trigger element not found', selector, 'warn');
        return;
      }

      const targetId = $trigger.data('tooltip-target');
      if (targetId) {
        // target模式：隐藏目标元素
        $('#' + targetId).hide();
      } else {
        // 标准模式：移除动态tooltip
        $('.kiko-tooltip-dynamic').remove();
      }
    },

    /**
     * 初始化指定元素的tooltip
     * @param {string|jQuery} selector - 元素选择器或jQuery对象
     * @param {Object} options - 配置选项
     */
    initElement: function (selector, options = {}) {
      const $elements = $(selector);
      if ($elements.length === 0) {
        kiko.core.log('Tooltip elements not found', selector, 'warn');
        return;
      }

      $elements.each(function () {
        initTooltip($(this), options);
      });
    },

    /**
     * 销毁tooltip
     * @param {string|jQuery} selector - 元素选择器或jQuery对象
     */
    destroy: function (selector) {
      const $elements = $(selector);
      $elements.each(function () {
        const $element = $(this);
        const targetId = $element.data('tooltip-target');
        const elementId = $element.attr('id');

        // 移除事件绑定
        $element.off('.kiko.tooltip');

        // 从click触发器集合中移除
        if (elementId) {
          clickTooltipTriggers.delete('#' + elementId);
        }

        // 处理tooltip容器
        if (targetId) {
          // target模式：隐藏目标元素并移除事件绑定
          const $container = $('#' + targetId);
          $container.hide().off('.kiko.tooltip');
        } else {
          // 标准模式：移除动态tooltip
          $('.kiko-tooltip-dynamic').remove();
        }

        // 移除标记属性
        $element.removeAttr('kiko-tooltip-loaded');
      });

      // 如果没有click触发器了，移除全局点击处理器
      if (clickTooltipTriggers.size === 0 && globalClickHandlerBound) {
        $(document).off('click.kiko.tooltip.global');
        globalClickHandlerBound = false;
      }
    },

    /**
     * 隐藏所有tooltip
     */
    hideAll: function () {
      hideAllTooltips();
    },

    /**
     * 设置默认配置
     * @param {Object} newDefaults - 新的默认配置
     */
    setDefaults: function (newDefaults) {
      $.extend(defaults, newDefaults);
    },

    /**
     * 刷新tooltip
     * 重新扫描页面中的tooltip元素并初始化
     * @param {string|jQuery} [selector] - 可选的选择器，不提供则刷新所有
     */
    refresh: function (selector) {
      if (selector) {
        this.initElement(selector);
      } else {
        // 重新初始化所有tooltip元素
        this.init();
      }

      // 日志记录
      kiko.core.log('tooltip已刷新');
      return this;
    },
  };

  // 导出到kiko命名空间
  kiko.ui.tooltip = methods;
})(jQuery, kiko);


// ---- utils/uploadimg.js ----
(function ($, kiko) {
  // 公共方法
  const methods = {
    /**
     * 初始化图片上传组件
     * @param {Object} options - 上传配置选项
     * @param {string} options.fileId - 文件输入框ID
     * @param {number} options.maxWidth - 最大宽度，默认680px
     * @param {number} options.rate - 压缩比率，默认0.8
     * @param {Function} options.callback - 图片处理完成后的回调函数
     * @returns {Object} uploadImg实例，支持链式调用
     */
    init: function (options) {
      kiko.core.log('初始化图片上传工具');

      const config = $.extend(
        {
          maxWidth: 680,
          rate: 0.8,
          callback: function () {},
        },
        options || {},
      );

      if (!config.fileId) {
        kiko.core.log('必须提供fileId参数', null, 'error');
        return this;
      }

      // 添加文件变更监听
      $('#' + config.fileId).on('change', function (e) {
        if ($(this).val() == '') {
          return;
        }
        if (this.files.length === 0) {
          return;
        }

        const file = this.files[0];
        const reader = new FileReader();

        reader.readAsDataURL(file);
        reader.onload = function (e) {
          const dataUrl = this.result;
          const image = new Image();

          image.src = dataUrl;
          image.onload = function (e) {
            // 处理图片尺寸
            let width = image.width,
              height = image.height;
            let scale = width / height;
            let width1, height1;

            // 创建Canvas进行处理
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');

            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // 计算调整后的尺寸
            if (width - height >= 0) {
              width1 = config.maxWidth;
              height1 = parseInt(width1 / scale);

              if (width >= width1) {
                canvas.width = width1;
                canvas.height = height1;
                ctx.drawImage(image, 0, 0, width1, height1);
              } else {
                canvas.width = width;
                canvas.height = height;
                ctx.drawImage(image, 0, 0, width, height);
              }
            } else {
              scale = height / width;
              height1 = config.maxWidth;
              width1 = parseInt(height1 / scale);

              if (height >= height1) {
                canvas.width = width1;
                canvas.height = height1;
                ctx.drawImage(image, 0, 0, width1, height1);
              } else {
                canvas.width = width;
                canvas.height = height;
                ctx.drawImage(image, 0, 0, width, height);
              }
            }

            // 转换为Base64数据URL
            const cropStr = canvas.toDataURL('image/jpeg', config.rate);

            // 调用回调函数
            config.callback(cropStr);
          };
        };
      });

      return this;
    },

    /**
     * 注册jQuery插件方法
     */
    registerJQueryPlugin: function () {
      $.uploadImg = function (options) {
        return methods.init(options);
      };
    },
  };

  // 导出到kiko命名空间
  kiko.utils.uploadImg = methods;

  // 自动注册jQuery插件方法
  methods.registerJQueryPlugin();
})(jQuery, window.kiko);


